FILES_CREATED = [0]


def write_file(path, content):
    """Writes one file as UTF-8 (needed for the Arabic strings)."""
    folder = os.path.dirname(path)
    if folder:
        os.makedirs(folder, exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    FILES_CREATED[0] += 1


