# ---- 1) RemoteConfigManager.kt ----
write_file(_PKG + "/data/RemoteConfigManager.kt", r'''package com.zevorix.assistant.data

import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONArray
import org.json.JSONObject

data class AppNotification(val title: String, val date: String, val content: String)
data class SupportInfo(val email: String, val whatsapp: String, val website: String)
data class RemoteConfigData(val support: SupportInfo, val notifications: List<AppNotification>)

object RemoteConfigManager {
    // Server URL comes from BuildConfig (GitHub Secrets / keys.properties), with a dev fallback.
    private val CONFIG_URL: String = com.zevorix.assistant.BuildConfig.REMOTE_CONFIG_URL
        .ifBlank { "https://raw.githubusercontent.com/YOUR_USERNAME/YOUR_REPO/main/config.json" }
    
    private val client = OkHttpClient()

    suspend fun fetchConfig(): RemoteConfigData? = withContext(Dispatchers.IO) {
        try {
            val request = Request.Builder().url(CONFIG_URL).build()
            val response = client.newCall(request).execute()
            if (!response.isSuccessful) return@withContext null
            val json = JSONObject(response.body?.string() ?: return@withContext null)
            
            val supportJson = json.optJSONObject("support")
            val support = SupportInfo(
                email = supportJson?.optString("email") ?: "tijara6@gmail.com",
                whatsapp = supportJson?.optString("whatsapp") ?: "",
                website = supportJson?.optString("website") ?: ""
            )
            
            val notifsList = mutableListOf<AppNotification>()
            val notifsArray = json.optJSONArray("notifications") ?: JSONArray()
            for (i in 0 until notifsArray.length()) {
                val n = notifsArray.getJSONObject(i)
                notifsList.add(AppNotification(
                    title = n.optString("title"),
                    date = n.optString("date"),
                    content = n.optString("content")
                ))
            }
            RemoteConfigData(support, notifsList)
        } catch (e: Exception) {
            Log.e("RemoteConfig", "Failed to fetch config", e)
            null
        }
    }
}
''')

