# Premium Coding — الاستكمال التلقائي (Auto-Continue) للمدفوعين عند بلوغ حد التوكنات
# الكشف يعتمد على إشارة المزوّد الحقيقية (finishReason / stop_reason / finish_reason)،
# والأجزاء تُدمج كنص خام ثم يُفصل الكود مرة واحدة في النهاية (حتى لا يضيع كود ولا ينقطع سياج ```).
# ==============================================================================

# 1. حالة آخر رد + دوال الاستكمال، قبل ask()
_replace_once(
    _PKG + "/data/AiChatService.kt",
    '    suspend fun ask(text: String, lang: AppLanguage): AiResult = withContext(Dispatchers.IO) {',
    '''    // آخر رد: نصه الخام (بدون قص) وهل توقف لأنه بلغ حد التوكنات لا لأنه انتهى.
    @Volatile private var lastRaw: String = ""
    @Volatile private var lastHitLimit: Boolean = false

    private fun geminiRawText(raw: String): String {
        val parts = JSONObject(raw).optJSONArray("candidates")?.optJSONObject(0)?.optJSONObject("content")?.optJSONArray("parts") ?: return ""
        val sb = StringBuilder()
        for (i in 0 until parts.length()) parts.optJSONObject(i)?.optString("text")?.let { sb.append(it) }
        return sb.toString()
    }

    private fun geminiHitLimit(raw: String): Boolean =
        JSONObject(raw).optJSONArray("candidates")?.optJSONObject(0)?.optString("finishReason") == "MAX_TOKENS"

    private suspend fun askProvider(provider: AiProvider, text: String, lang: AppLanguage): AiResult {
        lastRaw = ""
        lastHitLimit = false
        return when (provider) {
            AiProvider.GEMINI -> askGemini(text, lang)
            AiProvider.OPENAI -> askChatGPT(text, lang)
            AiProvider.CLAUDE -> askClaude(text, lang)
        }
    }

    /**
     * للمدفوعين فقط: إذا توقف الرد لأنه بلغ حد التوكنات، نطلب من النموذج المتابعة (حتى [maxLoops] مرات)
     * ثم ندمج الأجزاء ونفصل الكود مرة واحدة. لا يعمل أثناء تعديل ملف (حتى لا يُكتب ملف مقطوع).
     */
    private suspend fun askWithAutoContinue(
        provider: AiProvider,
        text: String,
        lang: AppLanguage,
        maxLoops: Int = 5
    ): AiResult {
        val first = askProvider(provider, text, lang)
        if (first !is AiResult.Success) return first
        if (!com.zevorix.assistant.data.LicenseManager.isUnlocked() || workingFile != null || !lastHitLimit) return first

        val merged = StringBuilder(lastRaw)
        val continuePrompt = lang.tr(
            "استكمل الإجابة السابقة من حيث توقفت بالضبط. لا تكرر ما كتبته سابقاً، ولا تكتب أي مقدمات أو اعتذارات. ابدأ مباشرة من النقطة التي توقفت عندها.",
            "Continue exactly from where you left off. Do not repeat what you wrote, do not add any introductions or apologies. Start directly from the cutoff point."
        )
        var added = 0
        while (lastHitLimit && added < maxLoops) {
            val next = askProvider(provider, continuePrompt, lang)
            if (next !is AiResult.Success || lastRaw.isBlank()) break
            merged.append(lastRaw)
            added++
        }
        if (added == 0) return first

        // التاريخ: نحذف أدوار "أكمل" الوسيطة ونحتفظ بالرد الكامل كرسالة واحدة.
        val full = merged.toString().trim()
        synchronized(lock) {
            repeat(added * 2) { if (history.isNotEmpty()) history.removeAt(history.size - 1) }
            if (history.isNotEmpty()) history[history.size - 1] = "model" to full
        }
        val (spoken, rawCode) = splitCode(full, lang)
        return AiResult.Success(spoken, applyEdit(rawCode))
    }

    suspend fun ask(text: String, lang: AppLanguage): AiResult = withContext(Dispatchers.IO) {'''
)

