# 2. استبدال ملف CreditsManager.kt بالكامل لدعم Firestore
write_file(_PKG + "/data/CreditsManager.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.content.SharedPreferences
import android.provider.Settings
import android.util.Log
import com.google.firebase.firestore.ktx.firestore
import com.google.firebase.ktx.Firebase
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.TimeZone

object CreditsManager {
    const val DAILY_FREE_MESSAGES = 50

    private const val PREFS = "credits_prefs"
    private const val KEY_FREE_USED = "free_used"
    private const val KEY_SAVED_DAY = "saved_day"
    private const val TAG = "CreditsManager"

    data class CreditsState(
        val freeUsed: Int = 0,
        val freeLimit: Int = DAILY_FREE_MESSAGES,
        val remaining: Int = DAILY_FREE_MESSAGES,
        val unlimited: Boolean = false
    )

    private val lock = Any()
    private var prefs: SharedPreferences? = null
    private var deviceId: String = ""
    private var isSynced: Boolean = false

    private val _state = MutableStateFlow(CreditsState())
    val state: StateFlow<CreditsState> = _state.asStateFlow()

    fun init(context: Context) {
        synchronized(lock) {
            if (prefs == null) {
                prefs = context.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
                deviceId = Settings.Secure.getString(context.contentResolver, Settings.Secure.ANDROID_ID)
            }
        }
        LicenseManager.init(context)
        synchronized(lock) {
            rollDayIfNeeded()
            publish()
        }
        syncWithCloud()
    }

    private fun todayString(): String {
        val format = SimpleDateFormat("yyyy-MM-dd", Locale.US)
        format.timeZone = TimeZone.getDefault()
        return format.format(Date())
    }

    private fun syncWithCloud() {
        if (deviceId.isEmpty()) return
        val db = Firebase.firestore
        val today = todayString()
        
        db.collection("quotas").document(deviceId).get()
            .addOnSuccessListener { document ->
                synchronized(lock) {
                    val savedDay = prefs?.getString(KEY_SAVED_DAY, "") ?: ""
                    val localUsed = prefs?.getInt(KEY_FREE_USED, 0) ?: 0
                    
                    if (document.exists() && document.getString("day") == today) {
                        // If cloud has usage for today, take the higher number between local and cloud
                        val cloudUsed = document.getLong("used")?.toInt() ?: 0
                        val maxUsed = maxOf(localUsed, cloudUsed)
                        if (savedDay != today) {
                            prefs?.edit()?.putString(KEY_SAVED_DAY, today)?.putInt(KEY_FREE_USED, maxUsed)?.apply()
                        } else {
                            prefs?.edit()?.putInt(KEY_FREE_USED, maxUsed)?.apply()
                        }
                    } else {
                        // New day, or no record yet. Update cloud with local today's usage.
                        if (savedDay != today) {
                             prefs?.edit()?.putString(KEY_SAVED_DAY, today)?.putInt(KEY_FREE_USED, 0)?.apply()
                        }
                        updateCloud(today, prefs?.getInt(KEY_FREE_USED, 0) ?: 0)
                    }
                    isSynced = true
                    publish()
                }
            }
            .addOnFailureListener { e ->
                Log.e(TAG, "Failed to sync quota with Firestore", e)
                synchronized(lock) { isSynced = true; publish() }
            }
    }

    private fun updateCloud(day: String, used: Int) {
        if (deviceId.isEmpty()) return
        val db = Firebase.firestore
        db.collection("quotas").document(deviceId)
            .set(mapOf("day" to day, "used" to used))
            .addOnFailureListener { e -> Log.e(TAG, "Failed to update cloud quota", e) }
    }

    fun canSend(): Boolean = synchronized(lock) {
        if (LicenseManager.isUnlocked()) return true
        rollDayIfNeeded()
        freeUsedToday() < DAILY_FREE_MESSAGES
    }

    fun recordSuccess() {
        synchronized(lock) {
            if (LicenseManager.isUnlocked()) { publish(); return }
            rollDayIfNeeded()
            val used = (freeUsedToday() + 1).coerceAtMost(DAILY_FREE_MESSAGES)
            prefs?.edit()?.putInt(KEY_FREE_USED, used)?.apply()
            updateCloud(todayString(), used) // Sync the new count to the cloud
            publish()
        }
    }

    fun freeLeft(): Int = synchronized(lock) {
        rollDayIfNeeded()
        (DAILY_FREE_MESSAGES - freeUsedToday()).coerceAtLeast(0)
    }

    fun refresh() {
        synchronized(lock) { publish() }
    }

    private fun freeUsedToday(): Int = prefs?.getInt(KEY_FREE_USED, 0) ?: 0

    private fun rollDayIfNeeded() {
        val p = prefs ?: return
        val today = todayString()
        val saved = p.getString(KEY_SAVED_DAY, "") ?: ""
        if (saved != today) {
            p.edit()
                .putInt(KEY_FREE_USED, 0)
                .putString(KEY_SAVED_DAY, today)
                .apply()
            updateCloud(today, 0)
        }
    }

    private fun publish() {
        val used = freeUsedToday()
        _state.value = CreditsState(
            freeUsed = used,
            freeLimit = DAILY_FREE_MESSAGES,
            remaining = (DAILY_FREE_MESSAGES - used).coerceAtLeast(0),
            unlimited = LicenseManager.isUnlocked()
        )
    }
}
''')

# ==============================================================================
# المرحلة 0 — إيقاف النزيف في نظام الحصة (Clobbering + fail-open + قواعد Firestore)
# ==============================================================================

# 1. CreditsManager.kt: ترانزاكشن بـ FieldValue.increment، لا كتابة لـ used قادمة من العميل،
#    وحجب الإرسال إلى أن تنجح المزامنة الأولى (fail-closed).
write_file(_PKG + "/data/CreditsManager.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.content.SharedPreferences
import android.provider.Settings
import android.util.Log
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.ktx.firestore
import com.google.firebase.ktx.Firebase
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.TimeZone

object CreditsManager {
    const val DAILY_FREE_MESSAGES = 50

    private const val PREFS = "credits_prefs"
    private const val KEY_FREE_USED = "free_used"
    private const val KEY_SAVED_DAY = "saved_day"
    private const val KEY_PREMIUM_USED = "premium_used"
    private const val COLLECTION = "quotas"
    private const val RETRY_INTERVAL_MS = 3000L
    private const val TAG = "CreditsManager"

    data class CreditsState(
        val freeUsed: Int = 0,
        val freeLimit: Int = DAILY_FREE_MESSAGES,
        val remaining: Int = DAILY_FREE_MESSAGES,
        val unlimited: Boolean = false
    )

    private val lock = Any()
    private var prefs: SharedPreferences? = null
    private var deviceId: String = ""

    // لا يُسمح بالإرسال المجاني قبل نجاح قراءة السحابة مرة واحدة على الأقل (fail-closed).
    private var synced: Boolean = false
    private var syncing: Boolean = false
    private var lastSyncAttemptMs: Long = 0L

    private val _state = MutableStateFlow(CreditsState())
    val state: StateFlow<CreditsState> = _state.asStateFlow()

    fun init(context: Context) {
        synchronized(lock) {
            if (prefs == null) {
                prefs = context.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
                deviceId = Settings.Secure.getString(context.contentResolver, Settings.Secure.ANDROID_ID) ?: ""
            }
        }
        LicenseManager.init(context)
        synchronized(lock) {
            rollDayIfNeeded() // محلي فقط: لا كتابة إلى السحابة هنا إطلاقاً
            publish()
        }
        syncWithCloud()
    }

    /** يوم UTC — يطابق حساب اليوم في قواعد Firestore (request.time). */
    private fun todayString(): String {
        val format = SimpleDateFormat("yyyy-MM-dd", Locale.US)
        format.timeZone = TimeZone.getTimeZone("UTC")
        return format.format(Date())
    }

    /** هل تمت مزامنة الحصة مع السحابة بنجاح؟ (تُستخدم لعرض «جارٍ التحقق» بدل «انتهت الحصة»). */
    fun isSynced(): Boolean = synchronized(lock) { synced }

    /** قراءة فقط: تأخذ الأعلى بين المحلي والسحابي. لا تكتب أي قيمة used من العميل. */
    private fun syncWithCloud() {
        if (deviceId.isEmpty()) return // بلا معرّف => يبقى مقفلاً (fail-closed)
        synchronized(lock) {
            if (syncing) return
            syncing = true
            lastSyncAttemptMs = System.currentTimeMillis()
        }
        Firebase.firestore.collection(COLLECTION).document(deviceId).get()
            .addOnSuccessListener { document ->
                synchronized(lock) {
                    rollDayIfNeeded()
                    if (document.exists() && document.getString("day") == todayString()) {
                        val cloudUsed = (document.getLong("used") ?: 0L).toInt()
                            .coerceIn(0, DAILY_FREE_MESSAGES)
                        if (cloudUsed > freeUsedToday()) {
                            prefs?.edit()?.putInt(KEY_FREE_USED, cloudUsed)?.apply()
                        }
                    }
                    synced = true
                    syncing = false
                    publish()
                }
            }
            .addOnFailureListener { e ->
                Log.e(TAG, "Quota sync failed (staying locked until it succeeds)", e)
                synchronized(lock) { syncing = false }
            }
    }

    private fun retrySyncIfNeeded() {
        val shouldRetry = synchronized(lock) {
            !synced && !syncing &&
                System.currentTimeMillis() - lastSyncAttemptMs >= RETRY_INTERVAL_MS
        }
        if (shouldRetry) syncWithCloud()
    }

    /**
     * يزيد العداد السحابي ذرّياً: increment(1) إن كان اليوم مطابقاً، وإلا set({day, used:1}) ليوم جديد.
     * لا تُكتب أبداً قيمة used محسوبة في العميل.
     */
    private fun recordUsageInCloud(day: String) {
        if (deviceId.isEmpty()) return
        val db = Firebase.firestore
        val ref = db.collection(COLLECTION).document(deviceId)
        db.runTransaction { tx ->
            val snap = tx.get(ref)
            if (snap.exists() && snap.getString("day") == day) {
                val current = snap.getLong("used") ?: 0L
                if (current >= DAILY_FREE_MESSAGES) return@runTransaction current
                tx.update(ref, "used", FieldValue.increment(1))
                current + 1L
            } else {
                tx.set(ref, mapOf("day" to day, "used" to 1))
                1L
            }
        }
            .addOnSuccessListener { cloudUsed ->
                synchronized(lock) {
                    val value = cloudUsed.toInt().coerceIn(0, DAILY_FREE_MESSAGES)
                    if (todayString() == day && value > freeUsedToday()) {
                        prefs?.edit()?.putInt(KEY_FREE_USED, value)?.apply()
                        publish()
                    }
                }
            }
            .addOnFailureListener { e -> Log.e(TAG, "Failed to record usage in cloud", e) }
    }

    fun canSend(): Boolean {
        // المرخّصون دائماً: ترخيصهم محلي ولا يعتمد على Firestore.
        if (LicenseManager.isUnlocked()) {
            val premiumUsed = prefs?.getInt(KEY_PREMIUM_USED, 0) ?: 0
            return premiumUsed < 2000
        }
        // أول سطر فعّال للمستخدم المجاني: لا إرسال قبل نجاح المزامنة.
        if (!isSynced()) {
            retrySyncIfNeeded()
            return false
        }
        return synchronized(lock) {
            rollDayIfNeeded()
            freeUsedToday() < DAILY_FREE_MESSAGES
        }
    }

    fun recordSuccess() {
        val day = todayString()
        synchronized(lock) {
            if (LicenseManager.isUnlocked()) {
                val premiumUsed = (prefs?.getInt(KEY_PREMIUM_USED, 0) ?: 0) + 1
                prefs?.edit()?.putInt(KEY_PREMIUM_USED, premiumUsed)?.apply()
                publish()
                return
            }
            rollDayIfNeeded()
            val used = (freeUsedToday() + 1).coerceAtMost(DAILY_FREE_MESSAGES)
            prefs?.edit()?.putInt(KEY_FREE_USED, used)?.apply()
            publish()
        }
        recordUsageInCloud(day)
    }

    fun freeLeft(): Int = synchronized(lock) {
        rollDayIfNeeded()
        (DAILY_FREE_MESSAGES - freeUsedToday()).coerceAtLeast(0)
    }

    fun refresh() {
        synchronized(lock) { publish() }
    }

    private fun freeUsedToday(): Int = prefs?.getInt(KEY_FREE_USED, 0) ?: 0

    /** تصفير محلي فقط عند تغيّر اليوم. السحابة تتجدد عبر الترانزاكشن/القواعد لا من هنا. */
    private fun rollDayIfNeeded() {
        val p = prefs ?: return
        val today = todayString()
        val saved = p.getString(KEY_SAVED_DAY, "") ?: ""
        if (saved != today) {
            p.edit()
                .putInt(KEY_FREE_USED, 0)
                .putString(KEY_SAVED_DAY, today)
                .apply()
        }
    }

    private fun publish() {
        val used = freeUsedToday()
        _state.value = CreditsState(
            freeUsed = used,
            freeLimit = DAILY_FREE_MESSAGES,
            remaining = (DAILY_FREE_MESSAGES - used).coerceAtLeast(0),
            unlimited = LicenseManager.isUnlocked()
        )
    }
}
''')

