# 3. قواعد Firestore (تُنشر من Console أو لاحقاً عبر firebase deploy --only firestore:rules)
write_file("firestore.rules", r'''rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    function dailyLimit() { return 50; }

    function pad(n) { return n < 10 ? '0' + string(n) : string(n); }

    // اليوم بتوقيت الخادم (UTC) — لا يمكن تزويره من العميل.
    function serverDay() {
      return string(request.time.year()) + '-' + pad(request.time.month()) + '-' + pad(request.time.day());
    }

    function validShape() {
      return request.resource.data.keys().hasOnly(['day', 'used'])
          && request.resource.data.keys().hasAll(['day', 'used'])
          && request.resource.data.day is string
          && request.resource.data.used is int
          && request.resource.data.day == serverDay()
          && request.resource.data.used >= 1
          && request.resource.data.used <= dailyLimit();
    }

    match /quotas/{deviceId} {
      // قراءة مستند واحد فقط (لا list).
      allow get: if true;
      allow list: if false;

      // أول استخدام: used = 1 حصراً، واليوم = يوم الخادم.
      allow create: if validShape() && request.resource.data.used == 1;

      // نفس اليوم: زيادة بمقدار 1 فقط (لا نقصان، لا قفزات، لا تجاوز 50).
      // يوم جديد: إعادة تعيين إلى 1 فقط، واليوم = يوم الخادم.
      allow update: if validShape() && (
          (resource.data.day == request.resource.data.day
              && request.resource.data.used == resource.data.used + 1)
          || (resource.data.day != request.resource.data.day
              && request.resource.data.used == 1)
      );

      allow delete: if false;
    }

    // كل ما عدا ذلك مرفوض.
    match /{document=**} {
      allow read, write: if false;
    }
  }
}
''')

# ==============================================================================
