_replace_once(
    _IME_SCREEN,
    '/** Bottom sheet listing what the assistant remembers; every row has a delete button that works at once. */\n',
    '/**\n'
    ' * True while the soft keyboard is open, whatever field opened it (chat field or a code box).\n'
    ' * Needed because on Android < 15 (adjustResize) WindowInsets.ime reports 0.\n'
    ' */\n'
    '@Composable\n'
    'private fun rememberKeyboardOpen(): Boolean {\n'
    '    val view = LocalView.current\n'
    '    val orientation = LocalConfiguration.current.orientation\n'
    '    var isOpen by remember { mutableStateOf(false) }\n'
    '    DisposableEffect(view, orientation) {\n'
    '        val rect = android.graphics.Rect()\n'
    '        var maxRootHeight = 0\n'
    '        val listener = android.view.ViewTreeObserver.OnGlobalLayoutListener {\n'
    '            view.getWindowVisibleDisplayFrame(rect)\n'
    '            val rootHeight = view.rootView.height\n'
    '            if (rootHeight > maxRootHeight) maxRootHeight = rootHeight\n'
    '            val covered = rootHeight - rect.bottom\n'
    '            isOpen = covered > rootHeight * 0.15f ||\n'
    '                (maxRootHeight > 0 && rootHeight < maxRootHeight * 0.85f)\n'
    '        }\n'
    '        view.viewTreeObserver.addOnGlobalLayoutListener(listener)\n'
    '        onDispose { view.viewTreeObserver.removeOnGlobalLayoutListener(listener) }\n'
    '    }\n'
    '    return isOpen\n'
    '}\n'
    '\n'
    '/** Bottom sheet listing what the assistant remembers; every row has a delete button that works at once. */\n'
)


# ==============================================================================
# ميزة "توليد الفيديو" عبر خادم خارجي (Render)
# ضع هذا القسم في نهاية setup.py. يعتمد على _PKG و write_file و insert_before و _replace_once.
# آمن لإعادة التشغيل: إن كان التعديل مطبّقاً مسبقاً يُتخطّى، وإن اختفت نقطة الإدراج يتوقف
# السكربت بخطأ واضح (RuntimeError) بدل أن يُفسد الملف بصمت.
# ==============================================================================
def _vid_replace(path, old, new):
    """
    Like _replace_once but SILENTLY skips when `new` already exists.
    ⚠️ This means an accidental pre-existing `new` string in the generated
    code will make this fix a NO-OP. After applying, grep for `new` to confirm.
    """
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if new in text:
        print(">> (skip) {} already contains the new block".format(path))
        return
    _replace_once(path, old, new)


def _vid_insert_before(path, anchor, insertion):
    """insert_before مع تخطٍّ هادئ إذا كان المُدرَج موجوداً أصلاً."""
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if insertion in text:
        return
    insert_before(path, anchor, insertion)


# ---- 0) ناقل الأحداث بين خدمة FCM والـ ViewModel (ملف جديد) ----
write_file(_PKG + "/service/VideoReadyBus.kt", r'''package com.zevorix.assistant.service

import kotlinx.coroutines.channels.BufferOverflow
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow

/**
 * Bridge between ZevorixFirebaseMessagingService (it has no access to the ViewModel)
 * and MainViewModel. Emitted when the server finished generating a video.
 */
object VideoReadyBus {
    data class Event(val url: String, val prompt: String)

    // replay: a push that arrives while no ViewModel exists yet is still delivered when one starts.
    private val _events = MutableSharedFlow<Event>(
        replay = 5,
        extraBufferCapacity = 8,
        onBufferOverflow = BufferOverflow.DROP_OLDEST
    )
    val events: SharedFlow<Event> = _events.asSharedFlow()

    /** The data comes from a push message, so only https links are accepted. */
    fun publish(url: String?, prompt: String?): Boolean {
        val clean = url?.trim().orEmpty()
        if (!clean.startsWith("https://", ignoreCase = true)) return false
        return _events.tryEmit(Event(clean, prompt?.trim().orEmpty()))
    }
}
''')


