# ---- 2) AiChatService.kt: generateVideoRequest ----
_vid_insert_before(
    _PKG + "/data/AiChatService.kt",
    "    suspend fun generateImage(prompt: String): ImageResult = withContext(Dispatchers.IO) {",
    r'''    /**
     * Asks the Render server to START generating a video. The server answers at once;
     * the finished video is announced later by a push message (type = video_ready).
     */
    suspend fun generateVideoRequest(
        prompt: String,
        deviceId: String,
        licenseKey: String = "",
        lang: AppLanguage = AppLanguage.ARABIC
    ): AiResult = withContext(Dispatchers.IO) {
        val url = com.zevorix.assistant.BuildConfig.VIDEO_SERVER_URL
            .ifBlank { "https://voiceassistantfinal.onrender.com/api/generate-video" }
        try {
            val body = JSONObject()
                .put("prompt", prompt)
                .put("licenseKey", licenseKey)
                .put("deviceId", deviceId)
                .toString()
                .toRequestBody("application/json; charset=utf-8".toMediaType())
            val request = Request.Builder().url(url).post(body).build()
            // longClient: Render's free tier may need up to a minute to wake up.
            longClient.newCall(request).await().use { response ->
                if (response.isSuccessful) {
                    AiResult.Success(lang.tr("تم بدء التوليد...", "Generation started..."))
                } else {
                    AiResult.Error(kindForBearer(response.code), "video server HTTP ${response.code}")
                }
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: IOException) {
            AiResult.Error(AiError.NETWORK, e.toString().take(160))
        } catch (e: Exception) {
            AiResult.Error(AiError.OTHER, e.toString().take(160))
        }
    }

''',
)


