# ==============================================================================
# ميزة جديدة: تنزيل/حفظ الفيديو + استقبال فيديو من المستخدم والتعديل عليه
# ------------------------------------------------------------------------------
# هذا القسم مُلحَق في نهاية setup.py فقط ولا يغيّر أي سطر سابق في الملف.
# يعتمد على: _PKG و write_file و insert_before و _replace_once و _vid_replace و _vid_insert_before.
# آمن لإعادة التشغيل: أي تعديل مطبّق مسبقاً يُتخطّى، وإن اختفت نقطة الإدراج يتوقف السكربت بخطأ واضح.
#
# 1) حفظ الفيديو: زر «حفظ» في بطاقة الفيديو ينزّل الرابط (https فقط) أو ينسخ الملف المحلي
#    إلى المعرض (Movies/Zevorix) دون أي إذن إضافي (MediaStore على Android 10+، وملفات التطبيق الخارجية قبله).
# 2) استقبال فيديو من المستخدم: نافذة «توليد فيديو» صار فيها زر «رفع فيديو للتعديل»؛ الفيديو يُنسخ إلى
#    ملفات التطبيق (حد أقصى 100MB) ثم يُرفع multipart إلى الخادم مع وصف التعديل.
# 3) عقد الخادم للتعديل (نفس الخادم ونفس إشعار video_ready):
#      POST {VIDEO_SERVER_URL مع استبدال generate-video بـ edit-video}   (multipart/form-data)
#      الحقول: video (الملف) ، prompt ، licenseKey ، deviceId
#      الرد: أي 2xx فوراً، ثم يُرسل الخادم إشعار FCM  type=video_ready  مع url و prompt كالمعتاد.
# ==============================================================================
def _vid_replace_between(path, start_marker, end_marker, new_block):
    """يستبدل المقطع من start_marker حتى قبل end_marker (كلٌّ منهما فريد). يُتخطّى إن كان new_block مطبّقاً."""
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if new_block in text:
        print(">> (skip) {} already contains the new block".format(path))
        return
    if text.count(start_marker) != 1 or text.count(end_marker) != 1:
        raise RuntimeError("Markers are not unique in {}: {!r} / {!r}".format(path, start_marker[:60], end_marker[:60]))
    start = text.index(start_marker)
    end = text.index(end_marker)
    if end <= start:
        raise RuntimeError("End marker comes before start marker in {}".format(path))
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text[:start] + new_block + text[end:])


# ---- A) VideoStorage.kt + VideoEditBridge (ملف جديد) ----
write_file(_PKG + "/data/VideoStorage.kt", r'''package com.zevorix.assistant.data

import android.content.ContentValues
import android.content.Context
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import android.provider.OpenableColumns
import androidx.core.content.FileProvider
import java.io.File
import java.io.IOException
import java.util.concurrent.TimeUnit
import okhttp3.OkHttpClient
import okhttp3.Request

/**
 * Video files of the app:
 *  - import a video picked by the user (copied into app storage, size-limited),
 *  - save a video (https link or app file) to the phone gallery: Movies/Zevorix,
 *  - give other apps a safe content:// uri to play an app file.
 * Every function that touches files or the network is blocking: call it off the main thread.
 */
object VideoStorage {
    /** Largest video the user may upload for editing. */
    const val MAX_UPLOAD_BYTES: Long = 100L * 1024 * 1024

    private const val FOLDER = "Zevorix"
    private const val KEEP_MS = 7L * 24 * 60 * 60 * 1000

    private val http: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(120, TimeUnit.SECONDS)
            .build()
    }

    private fun videosDir(context: Context): File =
        File(context.filesDir, "user_videos").apply { mkdirs() }

    /** True when [path] is a file inside the app's own video folder. */
    fun isAppVideo(context: Context, path: String): Boolean = try {
        val file = File(path)
        file.isFile && file.canonicalPath.startsWith(videosDir(context).canonicalPath + File.separator)
    } catch (e: Exception) {
        false
    }

    /** Copies the picked video into app storage. Returns null if it is not a video, too big or unreadable. */
    fun importPicked(context: Context, uri: Uri): File? {
        return try {
            val resolver = context.contentResolver
            val mime = resolver.getType(uri).orEmpty()
            if (mime.isNotEmpty() && !mime.startsWith("video/")) return null

            var declared = -1L
            resolver.query(uri, null, null, null, null)?.use { cursor ->
                val index = cursor.getColumnIndex(OpenableColumns.SIZE)
                if (cursor.moveToFirst() && index >= 0 && !cursor.isNull(index)) declared = cursor.getLong(index)
            }
            if (declared > MAX_UPLOAD_BYTES) return null

            cleanOld(context)
            val target = File(videosDir(context), "video_" + System.currentTimeMillis() + "." + extensionFor(mime))
            val input = resolver.openInputStream(uri) ?: return null
            var copied = 0L
            input.use { source ->
                target.outputStream().use { out ->
                    val buffer = ByteArray(64 * 1024)
                    while (true) {
                        val read = source.read(buffer)
                        if (read < 0) break
                        copied += read
                        if (copied > MAX_UPLOAD_BYTES) break
                        out.write(buffer, 0, read)
                    }
                }
            }
            if (copied <= 0L || copied > MAX_UPLOAD_BYTES) {
                target.delete()
                null
            } else {
                target
            }
        } catch (e: Exception) {
            null
        }
    }

    /** Saves the video to Movies/Zevorix. [source] is an https link or the path of an app video. */
    fun save(context: Context, source: String): Boolean {
        return try {
            val stamp = System.currentTimeMillis()
            if (source.startsWith("https://", ignoreCase = true)) {
                val temp = File(context.cacheDir, "download_$stamp.mp4")
                try {
                    download(source, temp)
                    if (temp.length() <= 0L) false else copyToMovies(context, temp, "zevorix_video_$stamp.mp4", "video/mp4")
                } finally {
                    temp.delete()
                }
            } else {
                if (!isAppVideo(context, source)) return false
                val file = File(source)
                copyToMovies(context, file, "zevorix_" + file.name, mimeFor(file))
            }
        } catch (e: Exception) {
            false
        }
    }

    /** content:// uri of an app video (null if the file is not one of the app's videos). */
    fun playableUri(context: Context, path: String): Uri? {
        if (!isAppVideo(context, path)) return null
        return try {
            FileProvider.getUriForFile(context, context.packageName + ".fileprovider", File(path))
        } catch (e: Exception) {
            null
        }
    }

    fun mimeFor(file: File): String = when (file.extension.lowercase()) {
        "webm" -> "video/webm"
        "3gp" -> "video/3gpp"
        "mkv" -> "video/x-matroska"
        else -> "video/mp4"
    }

    private fun extensionFor(mime: String): String = when (mime) {
        "video/webm" -> "webm"
        "video/3gpp" -> "3gp"
        "video/x-matroska" -> "mkv"
        else -> "mp4"
    }

    private fun download(url: String, target: File) {
        val request = Request.Builder().url(url).build()
        http.newCall(request).execute().use { response ->
            if (!response.isSuccessful) throw IOException("HTTP " + response.code)
            val body = response.body ?: throw IOException("empty body")
            body.byteStream().use { input ->
                target.outputStream().use { out -> input.copyTo(out) }
            }
        }
    }

    private fun copyToMovies(context: Context, source: File, name: String, mime: String): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val resolver = context.contentResolver
            val values = ContentValues().apply {
                put(MediaStore.Video.Media.DISPLAY_NAME, name)
                put(MediaStore.Video.Media.MIME_TYPE, mime)
                put(MediaStore.Video.Media.RELATIVE_PATH, Environment.DIRECTORY_MOVIES + "/" + FOLDER)
                put(MediaStore.Video.Media.IS_PENDING, 1)
            }
            val uri = resolver.insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI, values) ?: return false
            return try {
                val out = resolver.openOutputStream(uri) ?: throw IOException("no output stream")
                out.use { sink -> source.inputStream().use { it.copyTo(sink) } }
                values.clear()
                values.put(MediaStore.Video.Media.IS_PENDING, 0)
                resolver.update(uri, values, null, null)
                true
            } catch (e: Exception) {
                resolver.delete(uri, null, null)
                false
            }
        }
        // Android 8/9: app-specific external folder (no storage permission needed).
        val folder = File(context.getExternalFilesDir(Environment.DIRECTORY_MOVIES), FOLDER).apply { mkdirs() }
        source.copyTo(File(folder, name), overwrite = true)
        return true
    }

    /** Videos the user uploaded are kept for a week so the chat card can still play them. */
    private fun cleanOld(context: Context) {
        val limit = System.currentTimeMillis() - KEEP_MS
        videosDir(context).listFiles()?.forEach { if (it.isFile && it.lastModified() < limit) it.delete() }
    }
}

/** Hands the video chosen in the input bar to MainViewModel (the text message only carries the edit request). */
object VideoEditBridge {
    @Volatile
    private var pending: File? = null

    fun set(file: File) {
        val old = pending
        pending = file
        if (old != null && old != file) old.delete()
    }

    /** Returns the chosen video once and forgets it (the file stays for the chat card). */
    fun take(): File? {
        val file = pending
        pending = null
        return file
    }

    /** The user removed the choice before sending: the unsent copy is deleted. */
    fun clear() {
        pending?.delete()
        pending = null
    }
}
''')


