_vid_replace(
    _PKG + "/data/AiChatService.kt",
    "import okhttp3.Request\n",
    "import okhttp3.Request\n"
    "import okhttp3.RequestBody.Companion.asRequestBody\n",
)
_vid_insert_before(
    _PKG + "/data/AiChatService.kt",
    "    suspend fun generateImage(prompt: String): ImageResult = withContext(Dispatchers.IO) {",
    r'''    /**
     * Uploads a video picked by the user to the Render server and asks it to EDIT the video.
     * Same flow as generation: the server answers at once and the result arrives as a video_ready push.
     */
    suspend fun editVideoRequest(
        video: java.io.File,
        prompt: String,
        deviceId: String,
        licenseKey: String = "",
        lang: AppLanguage = AppLanguage.ARABIC
    ): AiResult = withContext(Dispatchers.IO) {
        val base = com.zevorix.assistant.BuildConfig.VIDEO_SERVER_URL
            .ifBlank { "https://voiceassistantfinal.onrender.com/api/generate-video" }
        val url = if (base.contains("generate-video")) {
            base.replace("generate-video", "edit-video")
        } else {
            base.trimEnd('/') + "/edit-video"
        }
        try {
            val body = okhttp3.MultipartBody.Builder()
                .setType(okhttp3.MultipartBody.FORM)
                .addFormDataPart("prompt", prompt)
                .addFormDataPart("licenseKey", licenseKey)
                .addFormDataPart("deviceId", deviceId)
                .addFormDataPart("video", video.name, video.asRequestBody(VideoStorage.mimeFor(video).toMediaType()))
                .build()
            val request = Request.Builder().url(url).post(body).build()
            // Uploading a big file needs far longer write/call limits than a normal chat request.
            val uploadClient = longClient.newBuilder()
                .writeTimeout(180, TimeUnit.SECONDS)
                .callTimeout(300, TimeUnit.SECONDS)
                .build()
            uploadClient.newCall(request).await().use { response ->
                if (response.isSuccessful) {
                    AiResult.Success(lang.tr("تم رفع الفيديو وبدأ التعديل...", "Video uploaded, editing started..."))
                } else {
                    AiResult.Error(kindForBearer(response.code), "video edit server HTTP ${response.code}")
                }
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: IOException) {
            AiResult.Error(AiError.NETWORK, e.toString().take(160))
        } catch (e: Exception) {
            AiResult.Error(AiError.OTHER, e.toString().take(160))
        }
    }

''',
)


