# ---- A) ناقل الأحداث بين خدمة FCM والـ ViewModel ----
write_file(_PKG + "/service/MusicReadyBus.kt", r'''package com.zevorix.assistant.service

import kotlinx.coroutines.channels.BufferOverflow
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow

/** Same idea as VideoReadyBus: emitted when the server finished generating a music track. */
object MusicReadyBus {
    data class Event(val url: String, val prompt: String)

    private val _events = MutableSharedFlow<Event>(
        replay = 5,
        extraBufferCapacity = 8,
        onBufferOverflow = BufferOverflow.DROP_OLDEST
    )
    val events: SharedFlow<Event> = _events.asSharedFlow()

    /** The data comes from a push message, so only https links are accepted. */
    fun publish(url: String?, prompt: String?): Boolean {
        val clean = url?.trim().orEmpty()
        if (!clean.startsWith("https://", ignoreCase = true)) return false
        return _events.tryEmit(Event(clean, prompt?.trim().orEmpty()))
    }
}
''')


# ---- B) MusicStorage.kt: حفظ المقطع في Music/Zevorix ----
write_file(_PKG + "/data/MusicStorage.kt", r'''package com.zevorix.assistant.data

import android.content.ContentValues
import android.content.Context
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import java.io.File
import java.io.IOException
import java.util.concurrent.TimeUnit
import okhttp3.OkHttpClient
import okhttp3.Request

/** Saves a generated music track (https link) to Music/Zevorix. Blocking: call off the main thread. */
object MusicStorage {
    private const val FOLDER = "Zevorix"

    private val http: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(120, TimeUnit.SECONDS)
            .build()
    }

    fun save(context: Context, url: String): Boolean {
        if (!url.startsWith("https://", ignoreCase = true)) return false
        return try {
            val stamp = System.currentTimeMillis()
            val extension = extensionOf(url)
            val temp = File(context.cacheDir, "music_$stamp.$extension")
            try {
                download(url, temp)
                if (temp.length() <= 0L) false
                else copyToMusic(context, temp, "zevorix_music_$stamp.$extension", mimeOf(extension))
            } finally {
                temp.delete()
            }
        } catch (e: Exception) {
            false
        }
    }

    private fun extensionOf(url: String): String {
        val path = url.substringBefore('?').substringAfterLast('/', "")
        return when (path.substringAfterLast('.', "").lowercase()) {
            "wav" -> "wav"
            "m4a" -> "m4a"
            "ogg" -> "ogg"
            else -> "mp3"
        }
    }

    private fun mimeOf(extension: String): String = when (extension) {
        "wav" -> "audio/wav"
        "m4a" -> "audio/mp4"
        "ogg" -> "audio/ogg"
        else -> "audio/mpeg"
    }

    private fun download(url: String, target: File) {
        val request = Request.Builder().url(url).build()
        http.newCall(request).execute().use { response ->
            if (!response.isSuccessful) throw IOException("HTTP " + response.code)
            val body = response.body ?: throw IOException("empty body")
            body.byteStream().use { input ->
                target.outputStream().use { out -> input.copyTo(out) }
            }
        }
    }

    private fun copyToMusic(context: Context, source: File, name: String, mime: String): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val resolver = context.contentResolver
            val values = ContentValues().apply {
                put(MediaStore.Audio.Media.DISPLAY_NAME, name)
                put(MediaStore.Audio.Media.MIME_TYPE, mime)
                put(MediaStore.Audio.Media.RELATIVE_PATH, Environment.DIRECTORY_MUSIC + "/" + FOLDER)
                put(MediaStore.Audio.Media.IS_PENDING, 1)
            }
            val uri = resolver.insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, values) ?: return false
            return try {
                val out = resolver.openOutputStream(uri) ?: throw IOException("no output stream")
                out.use { sink -> source.inputStream().use { it.copyTo(sink) } }
                values.clear()
                values.put(MediaStore.Audio.Media.IS_PENDING, 0)
                resolver.update(uri, values, null, null)
                true
            } catch (e: Exception) {
                resolver.delete(uri, null, null)
                false
            }
        }
        // Android 8/9: app-specific external folder (no storage permission needed).
        val folder = File(context.getExternalFilesDir(Environment.DIRECTORY_MUSIC), FOLDER).apply { mkdirs() }
        source.copyTo(File(folder, name), overwrite = true)
        return true
    }
}
''')


