# ==============================================================================
# ميزة جديدة: فحص أخطاء الكود محلياً + تشغيل ومعاينة HTML / JavaScript / SVG داخل التطبيق
# ------------------------------------------------------------------------------
# مُلحَق في نهاية setup.py فقط ولا يغيّر أي سطر سابق. آمن لإعادة التشغيل.
#
# - زر «فحص» في بطاقة الكود (بجانب نسخ/حفظ) يفتح نافذة بنتيجة الفحص مع أرقام الأسطر.
# - الفحص محلي بلا إنترنت: JSON (صارم) و XML/SVG (محلّل حقيقي) و HTML (توازن الوسوم + فحص <script>/<style> داخله)
#   وتوازن الأقواس والنصوص والتعليقات لـ js/ts/java/kotlin/c/cpp/cs/go/rust/swift/dart/php/css/gradle/python.
# - لملفات HTML و JS و SVG يظهر زر «تشغيل ومعاينة»: WebView معزول (بلا ملفات ولا واجهات جافا)
#   مع عرض رسائل الكونسول وأخطاء JavaScript الفعلية.
# - هذا فحص صياغة أساسي: لا يغني عن الترجمة الفعلية (gradle) ولا يشغّل Python/Java/Kotlin.
# ==============================================================================

# ---- A) CodeChecker.kt ----
write_file(_PKG + "/data/CodeChecker.kt", r'''package com.zevorix.assistant.data

import android.util.JsonReader
import android.util.JsonToken
import android.util.Xml
import com.zevorix.assistant.viewmodel.AppLanguage
import java.io.StringReader
import org.xmlpull.v1.XmlPullParser
import org.xmlpull.v1.XmlPullParserException

/**
 * Offline syntax checks for code blocks (no compiler involved).
 * It finds structural mistakes (unbalanced brackets, unclosed strings/tags, invalid JSON/XML) and reports line numbers.
 * It is a basic check: regex literals or unusual syntax may rarely give a false alarm.
 */
object CodeChecker {
    data class CheckIssue(val line: Int, val message: String)

    /** supported = false means this file type has no local check at all. */
    data class CheckResult(val supported: Boolean, val issues: List<CheckIssue>)

    private const val MAX_ISSUES = 12

    private val XML_KINDS = setOf("xml", "svg", "plist", "xsd", "xhtml")
    private val HTML_KINDS = setOf("html", "htm")
    private val BRACKET_KINDS = setOf(
        "js", "jsx", "ts", "tsx", "java", "kt", "kts", "c", "cpp", "h", "hpp", "cs",
        "go", "rs", "swift", "dart", "php", "css", "scss", "gradle", "py"
    )
    private val VOID_TAGS = setOf(
        "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"
    )
    private val OPTIONAL_CLOSE = setOf(
        "html", "head", "body", "p", "li", "dt", "dd", "tr", "td", "th", "thead", "tbody", "tfoot", "option", "colgroup"
    )

    /** HTML, JavaScript and SVG can be run in the preview WebView. */
    fun canRun(kind: String): Boolean = kind.lowercase() in setOf("html", "htm", "js", "svg")

    fun check(kind: String, code: String, lang: AppLanguage): CheckResult {
        val k = kind.lowercase()
        if (code.isBlank()) {
            return CheckResult(true, listOf(CheckIssue(1, lang.tr("الكود فارغ", "The code is empty"))))
        }
        val issues: List<CheckIssue> = when {
            k == "json" -> checkJson(code, lang)
            k in XML_KINDS -> checkXml(code, lang)
            k in HTML_KINDS -> checkHtml(code, lang)
            k in BRACKET_KINDS -> scanBrackets(code, k, lang, 0, "")
            else -> return CheckResult(false, emptyList())
        }
        return CheckResult(true, issues.take(MAX_ISSUES))
    }

    /** The page loaded by the preview. JavaScript is wrapped so that console line numbers equal the code's line numbers. */
    fun previewPage(kind: String, code: String): String = when (kind.lowercase()) {
        "js" -> "<!DOCTYPE html><html><head><meta charset=\"utf-8\">" +
            "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"></head><body><script>" +
            code.replace("</script", "<\\/script", ignoreCase = true) +
            "\n</script></body></html>"
        "svg" -> "<!DOCTYPE html><html><body style=\"margin:0;background:#fff\">" + code + "</body></html>"
        else -> code
    }

    // ------------------------------------------------------------------ JSON (strict)
    private fun checkJson(code: String, lang: AppLanguage): List<CheckIssue> {
        return try {
            val reader = JsonReader(StringReader(code))
            reader.skipValue()
            if (reader.peek() != JsonToken.END_DOCUMENT) {
                listOf(CheckIssue(1, lang.tr("JSON غير صالح: يوجد محتوى بعد نهاية الوثيقة", "Invalid JSON: extra content after the document")))
            } else {
                emptyList()
            }
        } catch (e: Exception) {
            val message = e.message.orEmpty()
            val line = Regex("line (\\d+)").find(message)?.groupValues?.get(1)?.toIntOrNull() ?: 1
            listOf(CheckIssue(line, lang.tr("JSON غير صالح: ", "Invalid JSON: ") + message.take(120)))
        }
    }

    // ------------------------------------------------------------------ XML / SVG
    private fun checkXml(code: String, lang: AppLanguage): List<CheckIssue> {
        return try {
            val parser = Xml.newPullParser()
            parser.setInput(StringReader(code))
            while (parser.next() != XmlPullParser.END_DOCUMENT) {
                // just walk the whole document: the parser throws on the first structural error
            }
            emptyList()
        } catch (e: XmlPullParserException) {
            val text = e.message.orEmpty().substringBefore(" (position").take(140)
            listOf(CheckIssue(maxOf(e.lineNumber, 1), lang.tr("XML غير صالح: ", "Invalid XML: ") + text))
        } catch (e: Exception) {
            listOf(CheckIssue(1, lang.tr("XML غير صالح: ", "Invalid XML: ") + e.toString().take(120)))
        }
    }

    // ------------------------------------------------------------------ HTML (tag balance + inline script/style)
    private fun checkHtml(code: String, lang: AppLanguage): List<CheckIssue> {
        val issues = ArrayList<CheckIssue>()
        class Tag(val name: String, val line: Int)
        val stack = ArrayList<Tag>()
        val n = code.length
        var i = 0
        var line = 1

        fun countLines(from: Int, to: Int) {
            for (k in from until minOf(to, n)) if (code[k] == '\n') line++
        }

        while (i < n && issues.size < MAX_ISSUES) {
            val lt = code.indexOf('<', i)
            if (lt < 0) break
            countLines(i, lt)
            i = lt
            if (code.startsWith("<!--", i)) {
                val end = code.indexOf("-->", i + 4)
                if (end < 0) {
                    issues.add(CheckIssue(line, lang.tr("تعليق <!-- غير مغلق", "Unterminated <!-- comment")))
                    break
                }
                countLines(i, end + 3)
                i = end + 3
                continue
            }
            if (i + 1 >= n) break
            val next = code[i + 1]
            if (next == '!' || next == '?') {
                val end = code.indexOf('>', i)
                if (end < 0) break
                countLines(i, end + 1)
                i = end + 1
                continue
            }
            val closing = next == '/'
            var p = i + (if (closing) 2 else 1)
            val nameStart = p
            while (p < n && (code[p].isLetterOrDigit() || code[p] == '-' || code[p] == ':')) p++
            if (p == nameStart) {
                i++ // a lone "<" inside text
                continue
            }
            val name = code.substring(nameStart, p).lowercase()

            // End of the tag, ignoring ">" inside quoted attribute values.
            var q = p
            var quote: Char? = null
            while (q < n) {
                val ch = code[q]
                if (quote != null) {
                    if (ch == quote) quote = null
                } else if (ch == '"' || ch == '\'') {
                    quote = ch
                } else if (ch == '>') {
                    break
                }
                q++
            }
            val tagLine = line
            if (q >= n) {
                issues.add(CheckIssue(tagLine, lang.tr("الوسم <$name غير مكتمل (ينقصه >)", "Tag <$name is incomplete (missing >)")))
                break
            }
            val selfClosing = code[q - 1] == '/'
            val tagText = code.substring(i, q + 1)
            countLines(i, q + 1)
            i = q + 1

            if (closing) {
                val index = stack.indexOfLast { it.name == name }
                if (index < 0) {
                    if (name !in VOID_TAGS && name !in OPTIONAL_CLOSE) {
                        issues.add(CheckIssue(tagLine, lang.tr("إغلاق </$name> بدون وسم فتح", "Closing </$name> without an opening tag")))
                    }
                } else {
                    for (k in stack.size - 1 downTo index + 1) {
                        val open = stack[k]
                        if (open.name !in OPTIONAL_CLOSE) {
                            issues.add(
                                CheckIssue(
                                    open.line,
                                    lang.tr(
                                        "الوسم <${open.name}> لم يُغلق قبل </$name> (سطر $tagLine)",
                                        "<${open.name}> is not closed before </$name> (line $tagLine)"
                                    )
                                )
                            )
                        }
                    }
                    while (stack.size > index) stack.removeAt(stack.size - 1)
                }
            } else if (name !in VOID_TAGS && !selfClosing) {
                stack.add(Tag(name, tagLine))
                if (name == "script" || name == "style") {
                    val endIndex = code.indexOf("</$name", i, ignoreCase = true)
                    if (endIndex < 0) {
                        issues.add(CheckIssue(tagLine, lang.tr("الوسم <$name> بلا إغلاق", "<$name> has no closing tag")))
                        break
                    }
                    val content = code.substring(i, endIndex)
                    val typed = tagText.contains("type", ignoreCase = true)
                    val runnable = name == "style" || !typed ||
                        tagText.contains("javascript", ignoreCase = true) || tagText.contains("module", ignoreCase = true)
                    if (runnable && content.isNotBlank()) {
                        val inner = if (name == "style") "css" else "js"
                        issues.addAll(scanBrackets(content, inner, lang, line - 1, if (name == "style") "CSS: " else "JS: "))
                    }
                    countLines(i, endIndex)
                    i = endIndex
                }
            }
        }
        for (open in stack) {
            if (open.name !in OPTIONAL_CLOSE && issues.size < MAX_ISSUES) {
                issues.add(CheckIssue(open.line, lang.tr("الوسم <${open.name}> لم يُغلق", "<${open.name}> is never closed")))
            }
        }
        return issues
    }

    // ------------------------------------------------------------------ brackets / strings / comments
    private fun scanBrackets(code: String, kind: String, lang: AppLanguage, offset: Int, prefix: String): List<CheckIssue> {
        val issues = ArrayList<CheckIssue>()
        class Open(val ch: Char, val line: Int, val resume: String?)
        val stack = ArrayList<Open>()

        val py = kind == "py"
        val lineComment: String? = when (kind) {
            "py" -> "#"
            "css" -> null
            else -> "//"
        }
        val quote3d = "\"".repeat(3)
        val quote3s = "'".repeat(3)
        val tripleDouble = py || kind in setOf("kt", "kts", "java", "swift", "dart")
        val tripleSingle = py || kind == "dart"
        val backtick = kind in setOf("js", "jsx", "ts", "tsx", "go")
        val interpolation = kind in setOf("kt", "kts", "dart")
        val n = code.length
        var i = 0
        var line = 1
        var str: String? = null
        var strLine = 1

        fun report(at: Int, text: String) {
            if (issues.size < MAX_ISSUES) issues.add(CheckIssue(at + offset, prefix + text))
        }

        while (i < n) {
            val c = code[i]
            if (c == '\n') {
                line++
                if (str == "\"" || str == "'") {
                    report(strLine, lang.tr("نص غير مغلق (علامة اقتباس بلا نهاية)", "Unterminated string (missing closing quote)"))
                    str = null
                }
                i++
                continue
            }

            val current = str
            if (current != null) {
                if (c == '\\' && !(kind == "go" && current == "`")) {
                    if (i + 1 < n && code[i + 1] == '\n') line++
                    i += 2
                    continue
                }
                if (code.startsWith(current, i)) {
                    i += current.length
                    str = null
                    continue
                }
                val interp = (interpolation && current.startsWith("\"")) || (current == "`" && kind != "go")
                if (interp && c == '$' && i + 1 < n && code[i + 1] == '{') {
                    stack.add(Open('{', line, current))
                    str = null
                    i += 2
                    continue
                }
                i++
                continue
            }

            if (!py && code.startsWith("/*", i)) {
                val end = code.indexOf("*/", i + 2)
                if (end < 0) {
                    report(line, lang.tr("تعليق /* غير مغلق", "Unterminated /* comment"))
                    return issues
                }
                for (k in i until end) if (code[k] == '\n') line++
                i = end + 2
                continue
            }
            if (lineComment != null && code.startsWith(lineComment, i)) {
                while (i < n && code[i] != '\n') i++
                continue
            }

            var opened: String? = null
            if (tripleDouble && code.startsWith(quote3d, i)) {
                opened = quote3d
            } else if (tripleSingle && code.startsWith(quote3s, i)) {
                opened = quote3s
            } else if (c == '"') {
                opened = "\""
            } else if (c == '\'') {
                opened = if (kind == "rs") {
                    // Rust lifetimes ('a) are not strings: only char literals ('x' or '\n') are.
                    if ((i + 2 < n && code[i + 2] == '\'') || (i + 1 < n && code[i + 1] == '\\')) "'" else null
                } else {
                    "'"
                }
            } else if (c == '`' && backtick) {
                opened = "`"
            }
            if (opened != null) {
                str = opened
                strLine = line
                i += opened.length
                continue
            }

            if (c == '(' || c == '[' || c == '{') {
                stack.add(Open(c, line, null))
            } else if (c == ')' || c == ']' || c == '}') {
                val want = when (c) {
                    ')' -> '('
                    ']' -> '['
                    else -> '{'
                }
                if (stack.isEmpty()) {
                    report(line, lang.tr("الإغلاق «$c» زائد: لا يوجد قوس مفتوح مقابل له", "Unexpected closing «$c»: nothing is open"))
                } else {
                    val top = stack.removeAt(stack.size - 1)
                    if (top.ch != want) {
                        report(
                            line,
                            lang.tr(
                                "الإغلاق «$c» لا يطابق «${top.ch}» المفتوح في السطر ${top.line}",
                                "Closing «$c» does not match «${top.ch}» opened on line ${top.line}"
                            )
                        )
                    } else if (top.resume != null) {
                        str = top.resume
                        strLine = top.line
                    }
                }
            }
            i++
        }

        if (str != null) report(strLine, lang.tr("نص غير مغلق", "Unterminated string"))
        for (open in stack) {
            report(open.line, lang.tr("«${open.ch}» مفتوح ولم يُغلق", "«${open.ch}» is opened but never closed"))
        }
        return issues
    }
}
''')


