# 2. إصلاح الترخيص: إضافة دالة getBackendKey في LicenseManager.kt لتوليد كود HMAC صالح للسيرفر
_vid_insert_before(
    _PKG + "/data/LicenseManager.kt",
    "    // ---------------- التفعيل ----------------\n",
    r'''    /** يرجع كود HMAC صالح للسيرفر (إما الكود الذي أدخله المستخدم، أو يتم توليده محلياً لمشتري Google Play) */
    fun getBackendKey(): String {
        if (!isUnlocked()) return ""
        val p = prefs ?: return ""
        val savedCode = p.getString("saved_backend_code", "")
        if (!savedCode.isNullOrBlank()) return savedCode
        val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        val nonce = (1..6).map { alphabet.random() }.joinToString("")
        val sig = sign(BuildConfig.LICENSE_SECRET, nonce)
        val generatedCode = "ZEV-$nonce-$sig"
        p.edit().putString("saved_backend_code", generatedCode).apply()
        return generatedCode
    }

'''
)
