# ==============================================================================
# التحويل إلى نظام الدفع المسبق الصارم (Pay-As-You-Go) — إلغاء الحصة المجانية بالكامل
#   - CreditsManager: يقرأ النقاط من licenses/{licenseKey} (بدل quotas/{deviceId}) ويخصم محلياً وسحابياً.
#   - MainViewModel.ensureQuota: يتطلب LicenseManager.isUnlocked() + رصيداً >= cost (نص = 1، صورة = 2).
#   - الفيديو والموسيقى يُخصمان في السيرفر (402 => INSUFFICIENT_CREDITS) ولا يمسّهما هذا القسم.
#   - MainScreen / PaywallSheet / AiSettingsSheet: إزالة كل اعتماد على unlimited / remaining / freeLimit.
#   - firestore.rules: يُسمح للتطبيق بتقليل credits فقط في licenses.
# هذا القسم يأتي بعد كل الأقسام السابقة عمداً: يستبدل CreditsManager.kt كاملاً ويعدّل النسخ النهائية من الملفات.
# ==============================================================================

def _payg_replace_all(path, old, new, expected):
    """Replaces every occurrence of `old`, failing loudly unless it appears exactly `expected` times."""
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if text.count(old) != expected:
        raise RuntimeError("Expected {} match(es) in {}: {!r} (found {})".format(
            expected, path, old[:70], text.count(old)))
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text.replace(old, new))


# ---- 1) CreditsManager.kt: استبدال كامل ----
write_file(_PKG + "/data/CreditsManager.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.content.SharedPreferences
import android.provider.Settings
import android.util.Log
import com.google.firebase.FirebaseApp
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.ktx.firestore
import com.google.firebase.ktx.Firebase
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

/**
 * نظام الدفع المسبق (Pay-As-You-Go): لا حصة مجانية.
 * - الرصيد يُقرأ من Firestore: licenses/{licenseKey}.credits ويُخزَّن محلياً.
 * - لا يُسمح بأي استخدام إلا بترخيص مفعّل (LicenseManager.isUnlocked) ورصيد كافٍ.
 * - الخصم بعد النجاح فقط: recordSuccess(cost) يخصم محلياً ثم سحابياً (increment سالب).
 */
object CreditsManager {
    private const val PREFS = "credits_prefs"
    private const val COLLECTION = "licenses"
    private const val TAG = "CreditsManager"
    private const val KEY_LOCAL_CREDITS = "local_credits"
    private const val KEY_FALLBACK_DEVICE_ID = "fallback_device_id"

    data class CreditsState(
        val credits: Int = 0,
        val unlocked: Boolean = false
    )

    private val lock = Any()
    private var prefs: SharedPreferences? = null
    private var appContext: Context? = null
    private var deviceId: String = ""

    private val _state = MutableStateFlow(CreditsState())
    val state: StateFlow<CreditsState> = _state.asStateFlow()

    fun init(context: Context) {
        synchronized(lock) {
            if (prefs == null) {
                val ctx = context.applicationContext
                val p = ctx.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
                prefs = p
                appContext = ctx
                val androidId = Settings.Secure.getString(ctx.contentResolver, Settings.Secure.ANDROID_ID)
                deviceId = if (!androidId.isNullOrBlank()) {
                    androidId
                } else {
                    p.getString(KEY_FALLBACK_DEVICE_ID, null)?.takeIf { it.isNotBlank() }
                        ?: UUID.randomUUID().toString().also {
                            p.edit().putString(KEY_FALLBACK_DEVICE_ID, it).apply()
                        }
                }
            }
        }
        LicenseManager.init(context)
        synchronized(lock) { publish() }
        syncWithCloud()
    }

    /** معرّف الجهاز نفسه المستخدم في طلبات الفيديو/الموسيقى وإشعارات FCM (فارغ قبل init). */
    fun currentDeviceId(): String = synchronized(lock) { deviceId }

    /** Firebase غير مهيّأ (بناء بدون google-services.json): نعمل بالرصيد المحلي ولا نلمس Firestore. */
    private fun firebaseAvailable(): Boolean {
        val ctx = appContext ?: return false
        return FirebaseApp.getApps(ctx).isNotEmpty()
    }

    fun canSend(): Boolean {
        if (!LicenseManager.isUnlocked()) return false
        return _state.value.credits > 0
    }

    /** يُستدعى بعد نجاح الطلب فقط. cost: نص = 1، صورة = 2. */
    fun recordSuccess(cost: Int = 1) {
        if (cost <= 0) return
        if (!LicenseManager.isUnlocked()) return
        val licenseKey = LicenseManager.getBackendKey()
        if (licenseKey.isEmpty()) return

        synchronized(lock) {
            val current = prefs?.getInt(KEY_LOCAL_CREDITS, 0) ?: 0
            val newCredits = (current - cost).coerceAtLeast(0)
            prefs?.edit()?.putInt(KEY_LOCAL_CREDITS, newCredits)?.apply()
            publish()
        }

        if (!firebaseAvailable()) return
        Firebase.firestore.collection(COLLECTION).document(licenseKey)
            .update("credits", FieldValue.increment(-cost.toLong()))
            .addOnFailureListener { e ->
                Log.e(TAG, "Failed to deduct credits", e)
                syncWithCloud() // السحابة هي المرجع: أعد الرصيد المحلي إلى قيمته الحقيقية
            }
    }

    fun syncWithCloud() {
        val licenseKey = LicenseManager.getBackendKey()
        if (licenseKey.isEmpty()) return
        if (!firebaseAvailable()) return

        Firebase.firestore.collection(COLLECTION).document(licenseKey).get()
            .addOnSuccessListener { doc ->
                if (doc.exists()) {
                    val cloudCredits = (doc.getLong("credits") ?: 0L).toInt().coerceAtLeast(0)
                    synchronized(lock) {
                        prefs?.edit()?.putInt(KEY_LOCAL_CREDITS, cloudCredits)?.apply()
                        publish()
                    }
                }
            }
            .addOnFailureListener { e -> Log.e(TAG, "Failed to sync credits", e) }
    }

    /** تُستدعى من LicenseManager/BillingManager عند تغيّر الترخيص: تحدّث الواجهة ثم تزامن الرصيد. */
    fun refresh() {
        synchronized(lock) { publish() }
        syncWithCloud()
    }

    private fun publish() {
        val credits = prefs?.getInt(KEY_LOCAL_CREDITS, 0) ?: 0
        _state.value = CreditsState(
            credits = credits,
            unlocked = LicenseManager.isUnlocked()
        )
    }
}
''')

