write_file("firestore.rules", r'''rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // أقصى نقاط يخصمها التطبيق في عملية واحدة (نص = 1، صورة = 2). الفيديو/الموسيقى يخصمهما السيرفر (Admin SDK).
    function maxClientCost() { return 2; }

    match /licenses/{licenseKey} {
      // قراءة مستند واحد بمعرفة الكود فقط. list مرفوض حتى لا تُسرَّب أكواد الترخيص وأرصدتها.
      allow get: if true;
      allow list: if false;

      // التطبيق يستطيع تقليل credits فقط: لا زيادة، ولا لمس أي حقل آخر، ولا إنشاء/حذف.
      allow update: if request.resource.data.diff(resource.data).affectedKeys().hasOnly(['credits'])
                    && resource.data.credits is int
                    && request.resource.data.credits is int
                    && request.resource.data.credits >= 0
                    && request.resource.data.credits < resource.data.credits
                    && resource.data.credits - request.resource.data.credits <= maxClientCost();
      allow create, delete: if false;
    }

    match /quotas/{deviceId} {
      allow read, write: if false; // لم نعد نستخدم الحصة المجانية
    }

    match /{document=**} {
      allow read, write: if false;
    }
  }
}
''')

