# 5) LicenseVerifier.kt (جديد)
write_file(_FR_VER, r'''package com.zevorix.assistant.data

import com.zevorix.assistant.BuildConfig
import net.i2p.crypto.eddsa.EdDSAEngine
import net.i2p.crypto.eddsa.EdDSAPrivateKey
import net.i2p.crypto.eddsa.EdDSAPublicKey
import net.i2p.crypto.eddsa.spec.EdDSANamedCurveTable
import net.i2p.crypto.eddsa.spec.EdDSAPrivateKeySpec
import net.i2p.crypto.eddsa.spec.EdDSAPublicKeySpec
import java.security.MessageDigest

/**
 * التحقق من أكواد الترخيص بتوقيع Ed25519 (غير متماثل).
 *
 * صيغة الكود: ZEV-<nonce 8 أحرف من A-Z2-7>-<base58(signature 64 بايت)>
 * الرسالة الموقّعة: بايتات UTF-8 للـ nonce فقط (متوافقة مع index.js في الـ backend).
 * base58: أبجدية Bitcoin.
 *
 * المفتاح العام فقط داخل الـ APK؛ المفتاح الخاص عند المطوّر/السيرفر ولا يوضع هنا أبداً.
 */
object LicenseVerifier {
    const val PUBLIC_KEY_HEX = "__PUBLIC_KEY_HEX__"
    const val PREFIX = "ZEV"
    const val NONCE_LEN = 8
    const val NONCE_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"

    private const val SIGNATURE_BYTES = 64
    private const val PUBLIC_KEY_BYTES = 32
    private const val MAX_CODE_LENGTH = 160
    private const val BASE58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"

    class ParsedCode(val code: String, val nonce: String, val signature: ByteArray)

    fun isConfigured(): Boolean = PUBLIC_KEY_HEX.length == 64

    /** يزيل المسافات ويحوّل PREFIX و nonce فقط لأحرف كبيرة (التوقيع base58 حساس لحالة الأحرف). */
    fun normalize(raw: String): String {
        val compact = raw.filter { !it.isWhitespace() }
        val parts = compact.split("-")
        if (parts.size != 3) return compact
        return parts[0].uppercase() + "-" + parts[1].uppercase() + "-" + parts[2]
    }

    /** يفكك الكود ويتحقق من الشكل والطول فقط (لا يتحقق من التوقيع). */
    fun parse(raw: String): ParsedCode? {
        val code = normalize(raw)
        if (code.isEmpty() || code.length > MAX_CODE_LENGTH) return null
        val parts = code.split("-")
        if (parts.size != 3) return null
        if (parts[0] != PREFIX) return null
        val nonce = parts[1]
        if (nonce.length != NONCE_LEN || !nonce.all { it in NONCE_ALPHABET }) return null
        val signature = base58Decode(parts[2]) ?: return null
        if (signature.size != SIGNATURE_BYTES) return null
        return ParsedCode(code, nonce, signature)
    }

    /** يتحقق من توقيع Ed25519 للكود. أي خطأ = false. */
    fun verify(raw: String): Boolean {
        if (!isConfigured()) return false
        val parsed = parse(raw) ?: return false
        val publicKey = hexToBytes(PUBLIC_KEY_HEX) ?: return false
        if (publicKey.size != PUBLIC_KEY_BYTES) return false
        return try {
            val spec = EdDSANamedCurveTable.getByName("Ed25519")
            val key = EdDSAPublicKey(EdDSAPublicKeySpec(publicKey, spec))
            val engine = EdDSAEngine(MessageDigest.getInstance(spec.hashAlgorithm))
            engine.initVerify(key)
            engine.update(parsed.nonce.toByteArray(Charsets.UTF_8))
            engine.verify(parsed.signature)
        } catch (e: Exception) {
            false
        }
    }

    /** لأدوات الاختبار فقط: يولّد كوداً موقّعاً من seed خاص (32 بايت hex). يرفض العمل في release. */
    @JvmStatic
    fun signForTesting(nonce: String, privateKeySeedHex: String): String {
        check(BuildConfig.DEBUG) { "signForTesting is available in debug builds only" }
        require(nonce.length == NONCE_LEN && nonce.all { it in NONCE_ALPHABET }) { "bad nonce" }
        val seed = requireNotNull(hexToBytes(privateKeySeedHex)) { "bad seed hex" }
        require(seed.size == PUBLIC_KEY_BYTES) { "seed must be 32 bytes" }
        val spec = EdDSANamedCurveTable.getByName("Ed25519")
        val privateKey = EdDSAPrivateKey(EdDSAPrivateKeySpec(seed, spec))
        val engine = EdDSAEngine(MessageDigest.getInstance(spec.hashAlgorithm))
        engine.initSign(privateKey)
        engine.update(nonce.toByteArray(Charsets.UTF_8))
        val signature = engine.sign()
        return PREFIX + "-" + nonce + "-" + base58Encode(signature)
    }

    // ---------------- base58 (Bitcoin alphabet) ----------------

    private fun base58Decode(input: String): ByteArray? {
        if (input.isEmpty()) return null
        val digits = ByteArray(input.length)
        for (i in input.indices) {
            val d = BASE58.indexOf(input[i])
            if (d < 0) return null
            digits[i] = d.toByte()
        }
        var zeros = 0
        while (zeros < digits.size && digits[zeros].toInt() == 0) zeros++
        val decoded = ByteArray(input.length)
        var outputStart = decoded.size
        var inputStart = zeros
        while (inputStart < digits.size) {
            outputStart--
            decoded[outputStart] = divmod(digits, inputStart, 58, 256)
            if (digits[inputStart].toInt() == 0) inputStart++
        }
        while (outputStart < decoded.size && decoded[outputStart].toInt() == 0) outputStart++
        return decoded.copyOfRange(outputStart - zeros, decoded.size)
    }

    private fun base58Encode(data: ByteArray): String {
        if (data.isEmpty()) return ""
        val input = data.copyOf()
        var zeros = 0
        while (zeros < input.size && input[zeros].toInt() == 0) zeros++
        val encoded = CharArray(input.size * 2)
        var outputStart = encoded.size
        var inputStart = zeros
        while (inputStart < input.size) {
            outputStart--
            encoded[outputStart] = BASE58[divmod(input, inputStart, 256, 58).toInt() and 0xFF]
            if (input[inputStart].toInt() == 0) inputStart++
        }
        while (outputStart < encoded.size && encoded[outputStart] == BASE58[0]) outputStart++
        repeat(zeros) {
            outputStart--
            encoded[outputStart] = BASE58[0]
        }
        return String(encoded, outputStart, encoded.size - outputStart)
    }

    private fun divmod(number: ByteArray, firstDigit: Int, base: Int, divisor: Int): Byte {
        var remainder = 0
        for (i in firstDigit until number.size) {
            val digit = number[i].toInt() and 0xFF
            val temp = remainder * base + digit
            number[i] = (temp / divisor).toByte()
            remainder = temp % divisor
        }
        return remainder.toByte()
    }

    private fun hexToBytes(hex: String): ByteArray? {
        if (hex.length % 2 != 0) return null
        val out = ByteArray(hex.length / 2)
        for (i in out.indices) {
            val hi = Character.digit(hex[i * 2], 16)
            val lo = Character.digit(hex[i * 2 + 1], 16)
            if (hi < 0 || lo < 0) return null
            out[i] = ((hi shl 4) or lo).toByte()
        }
        return out
    }
}
'''.replace("__PUBLIC_KEY_HEX__", _LICENSE_PUBLIC_KEY_HEX))

# 6) LicenseManager.kt: استبدال كامل (Ed25519، بلا أي سر مشترك)
write_file(_FR_LIC, r'''package com.zevorix.assistant.data

import android.content.Context
import android.content.SharedPreferences
import android.util.Log

/**
 * ملاحظات أمنية:
 *
 * 1) التحقق بتوقيع Ed25519 غير متماثل: داخل الـ APK مفتاح عام فقط (LicenseVerifier.PUBLIC_KEY_HEX).
 *    المفتاح الخاص عند المطوّر/السيرفر، فلا يمكن توليد أكواد صالحة من فك الـ APK.
 * 2) صيغة الكود: ZEV-<nonce 8 أحرف>-<base58(توقيع 64 بايت)>. الرسالة الموقّعة = nonce (UTF-8).
 *    أكواد الإصدارات القديمة (HMAC) مرفوضة.
 * 3) الحالة محلية: مسح بيانات التطبيق يزيل الترخيص والـ nonces المستخدمة (أعد الكود نفسه للتفعيل من جديد).
 *    الرصيد نفسه مرجعه السحابة (CreditsManager).
 * 4) حالة الاشتراك تُكتب من طبقة Billing ويُعاد التحقق منها عند كل تشغيل.
 */
object LicenseManager {

    sealed class RedeemResult {
        object Success : RedeemResult()
        object Invalid : RedeemResult()
        object AlreadyUsed : RedeemResult()
        object NotConfigured : RedeemResult()
        data class Locked(val minutes: Int) : RedeemResult()
    }

    data class RedeemHistoryEntry(val codeShort: String, val timestamp: Long)

    private const val TAG = "LicenseManager"
    private const val PREFS = "license_prefs"
    private const val KEY_LIFETIME = "lifetime"
    private const val KEY_USED_NONCES = "used_nonces"
    private const val KEY_HISTORY = "history"
    private const val KEY_FAILS = "fails"
    private const val KEY_LOCK_UNTIL = "lock_until"
    private const val KEY_SUB_ACTIVE = "sub_active"
    private const val KEY_SUB_EXPIRY = "sub_expiry"
    private const val KEY_BACKEND_CODE = "saved_backend_code"
    private const val KEY_PENDING_PLAY_TOKEN = "pending_play_purchase_token"

    private const val MAX_FAILS = 5
    private const val LOCK_MINUTES = 10
    private const val MAX_HISTORY = 20

    private val lock = Any()
    private var prefs: SharedPreferences? = null

    fun init(context: Context) {
        synchronized(lock) {
            if (prefs == null) {
                prefs = context.applicationContext
                    .getSharedPreferences(PREFS, Context.MODE_PRIVATE)
            }
        }
    }

    // ---------------- الحالة ----------------

    fun hasLifetime(): Boolean = prefs?.getBoolean(KEY_LIFETIME, false) ?: false

    /** expiry = 0 يعني بلا تاريخ انتهاء معروف (يعتمد على Billing). */
    fun subscriptionActive(): Boolean {
        val p = prefs ?: return false
        if (!p.getBoolean(KEY_SUB_ACTIVE, false)) return false
        val expiry = p.getLong(KEY_SUB_EXPIRY, 0L)
        return expiry == 0L || expiry > System.currentTimeMillis()
    }

    /** هل التطبيق مفتوح (ترخيص دائم أو اشتراك نشط)؟ */
    fun isUnlocked(): Boolean = hasLifetime() || subscriptionActive()

    /** تُستدعى من طبقة Billing بعد التحقق من حالة الاشتراك. */
    fun setSubscription(active: Boolean, expiryMillis: Long = 0L) {
        synchronized(lock) {
            prefs?.edit()
                ?.putBoolean(KEY_SUB_ACTIVE, active)
                ?.putLong(KEY_SUB_EXPIRY, expiryMillis)
                ?.apply()
        }
        CreditsManager.refresh()
    }

    // ---------------- مفتاح الـ backend ----------------

    /**
     * الكود الموقّع الذي يعرّف الترخيص عند السيرفر وفي Firestore (licenses/{code}).
     * يرجع "" إذا لم يُفعَّل كود حقيقي بعد: لا يُولَّد كود محلياً أبداً.
     */
    fun getBackendKey(): String {
        if (!isUnlocked()) return ""
        val saved = prefs?.getString(KEY_BACKEND_CODE, "") ?: ""
        return if (saved.isNotBlank()) saved else ""
    }

    fun hasBackendKey(): Boolean = getBackendKey().isNotEmpty()

    // ---------------- منح الترخيص (Google Play) ----------------

    /**
     * يمنح الترخيص الدائم بعد أن يصدر السيرفر كوداً موقّعاً لعملية شراء Play.
     * يتحقق من توقيع Ed25519 قبل أي تغيير؛ يرجع false إذا كان الكود غير صالح.
     */
    fun grantLifetime(code: String): Boolean {
        val normalized = LicenseVerifier.normalize(code)
        if (!LicenseVerifier.verify(normalized)) return false
        synchronized(lock) {
            val p = prefs ?: return false
            p.edit()
                .putBoolean(KEY_LIFETIME, true)
                .putString(KEY_BACKEND_CODE, normalized)
                .apply()
        }
        CreditsManager.refresh()
        return true
    }

    /** للاختبار في نسخ debug فقط (DebugPurchaseSimulator): يفتح الترخيص برصيد 0 وبدون backend key. */
    fun grantLifetimeDebug() {
        if (!com.zevorix.assistant.BuildConfig.DEBUG) return
        synchronized(lock) {
            prefs?.edit()?.putBoolean(KEY_LIFETIME, true)?.apply()
        }
        CreditsManager.refresh()
    }

    // ---------------- توكن شراء Play المعلّق (قبل أن يحوّله السيرفر إلى كود) ----------------

    fun pendingPlayToken(): String = prefs?.getString(KEY_PENDING_PLAY_TOKEN, "") ?: ""

    fun savePendingPlayToken(token: String) {
        synchronized(lock) {
            prefs?.edit()?.putString(KEY_PENDING_PLAY_TOKEN, token)?.apply()
        }
    }

    fun clearPendingPlayToken() {
        synchronized(lock) {
            prefs?.edit()?.remove(KEY_PENDING_PLAY_TOKEN)?.apply()
        }
    }

    // ---------------- التفعيل ----------------

    fun redeem(context: Context, rawCode: String): RedeemResult {
        init(context)
        synchronized(lock) {
            val p = prefs ?: return RedeemResult.Invalid

            if (!LicenseVerifier.isConfigured()) return RedeemResult.NotConfigured

            val now = System.currentTimeMillis()
            val lockUntil = p.getLong(KEY_LOCK_UNTIL, 0L)
            if (lockUntil > now) {
                val mins = (((lockUntil - now) + 59_999L) / 60_000L).toInt().coerceAtLeast(1)
                return RedeemResult.Locked(mins)
            }

            val parsed = LicenseVerifier.parse(rawCode)
            if (parsed == null || !LicenseVerifier.verify(parsed.code)) {
                return registerFailure(p, now)
            }

            val used = p.getStringSet(KEY_USED_NONCES, emptySet())!!.toMutableSet()
            if (parsed.nonce in used) return RedeemResult.AlreadyUsed

            used.add(parsed.nonce)
            p.edit()
                .putStringSet(KEY_USED_NONCES, used)
                .putBoolean(KEY_LIFETIME, true)
                .putString(KEY_BACKEND_CODE, parsed.code)
                .putInt(KEY_FAILS, 0)
                .putLong(KEY_LOCK_UNTIL, 0L)
                .apply()
            recordHistory(p, "${LicenseVerifier.PREFIX}-${parsed.nonce.take(3)}…", now)
            CreditsManager.refresh()
            return RedeemResult.Success
        }
    }

    fun history(context: Context): List<RedeemHistoryEntry> {
        init(context)
        val raw = prefs?.getString(KEY_HISTORY, "") ?: ""
        if (raw.isEmpty()) return emptyList()
        return raw.split("\n").mapNotNull { line ->
            val i = line.indexOf('|')
            if (i <= 0) return@mapNotNull null
            val ts = line.substring(0, i).toLongOrNull() ?: return@mapNotNull null
            RedeemHistoryEntry(codeShort = line.substring(i + 1), timestamp = ts)
        }
    }

    // ---------------- داخلي ----------------

    private fun registerFailure(p: SharedPreferences, now: Long): RedeemResult {
        val fails = p.getInt(KEY_FAILS, 0) + 1
        return if (fails >= MAX_FAILS) {
            p.edit()
                .putInt(KEY_FAILS, 0)
                .putLong(KEY_LOCK_UNTIL, now + LOCK_MINUTES * 60_000L)
                .apply()
            RedeemResult.Locked(LOCK_MINUTES)
        } else {
            p.edit().putInt(KEY_FAILS, fails).apply()
            RedeemResult.Invalid
        }
    }

    private fun recordHistory(p: SharedPreferences, codeShort: String, ts: Long) {
        val old = history(p)
        val entries = (listOf("$ts|$codeShort") + old).take(MAX_HISTORY)
        p.edit().putString(KEY_HISTORY, entries.joinToString("\n")).apply()
    }

    private fun history(p: SharedPreferences): List<String> {
        val raw = p.getString(KEY_HISTORY, "") ?: ""
        return if (raw.isEmpty()) emptyList() else raw.split("\n")
    }
}
''')

