_replace_once(
    _FR_BILL,
    "    /** Google تُرجع المبلغ تلقائياً إن لم يُؤكَّد الشراء خلال 3 أيام. */\n",
    r'''    /**
     * شراء الترخيص الدائم من Play: نحفظ التوكن أولاً (يبقى بعد قتل التطبيق)، ثم نطلب من السيرفر كوداً موقّعاً،
     * ونتحقق منه بـ LicenseManager.grantLifetime(code)، وبعدها فقط نؤكّد الشراء (acknowledge) ونمسح التوكن المعلّق.
     */
    private fun handleLifetimePurchase(purchase: Purchase) {
        if (LicenseManager.hasBackendKey()) {
            acknowledgeIfNeeded(purchase)
            LicenseManager.clearPendingPlayToken()
            return
        }
        val token = purchase.purchaseToken
        LicenseManager.savePendingPlayToken(token)
        if (provisioning) return
        provisioning = true
        scope.launch {
            try {
                if (provisionWithRetry(token)) {
                    acknowledgeIfNeeded(purchase)
                    LicenseManager.clearPendingPlayToken()
                }
            } finally {
                provisioning = false
            }
        }
    }

    /** يعيد محاولة توكن شراء محفوظ لم يتحوّل إلى كود بعد (انقطاع شبكة / قُتل التطبيق). */
    fun retryPendingProvision() {
        try {
            val token = LicenseManager.pendingPlayToken()
            if (token.isEmpty()) return
            if (LicenseManager.hasBackendKey()) {
                LicenseManager.clearPendingPlayToken()
                return
            }
            if (provisioning) return
            provisioning = true
            scope.launch {
                try {
                    if (provisionWithRetry(token)) {
                        acknowledgeToken(token)
                        LicenseManager.clearPendingPlayToken()
                    }
                } finally {
                    provisioning = false
                }
            }
        } catch (e: Exception) {
            Log.w(TAG, "retryPendingProvision failed", e)
        }
    }

    private suspend fun provisionWithRetry(token: String): Boolean {
        repeat(PROVISION_ATTEMPTS) { attempt ->
            if (provision(token)) return true
            if (attempt < PROVISION_ATTEMPTS - 1) delay(PROVISION_RETRY_DELAY_MS)
        }
        return false
    }

    private suspend fun provision(token: String): Boolean {
        return try {
            when (val r = ai.provisionPlayPurchase(token, CreditsManager.currentDeviceId())) {
                is AiResult.Success -> {
                    val granted = LicenseManager.grantLifetime(r.text)
                    if (!granted) Log.w(TAG, "provision: server returned a license code with an invalid signature")
                    granted
                }
                is AiResult.Error -> {
                    Log.w(TAG, "provision failed: ${r.kind} ${r.detail}")
                    false
                }
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            Log.w(TAG, "provision error", e)
            false
        }
    }

    /** تأكيد الشراء بالتوكن مباشرة (عند إعادة المحاولة لا يتوفر كائن Purchase). */
    private fun acknowledgeToken(token: String) {
        val c = client ?: return
        if (!c.isReady) return
        scope.launch {
            try {
                val r = c.acknowledgePurchase(
                    AcknowledgePurchaseParams.newBuilder().setPurchaseToken(token).build()
                )
                if (r.responseCode != BillingClient.BillingResponseCode.OK) {
                    Log.w(TAG, "acknowledge(token) failed: ${r.responseCode} ${r.debugMessage}")
                }
            } catch (e: Exception) {
                Log.w(TAG, "acknowledge(token) error", e)
            }
        }
    }

    /** Google تُرجع المبلغ تلقائياً إن لم يُؤكَّد الشراء خلال 3 أيام. */
'''
)
