# 1) DocumentGenerator.kt
write_file(_PKG + "/data/DocumentGenerator.kt", r'''package com.zevorix.assistant.data

import android.content.ContentValues
import android.content.Context
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import java.io.File
import java.io.IOException

/** Saves generated documents (HTML) into Downloads/ZevorixDocs so a browser, Word or any viewer can open them. */
object DocumentGenerator {

    private const val FOLDER = "ZevorixDocs"

    fun saveDocument(context: Context, fileName: String, htmlContent: String): Uri? {
        val displayName = if (fileName.endsWith(".html", ignoreCase = true)) fileName else "$fileName.html"
        val bytes = htmlContent.toByteArray(Charsets.UTF_8)

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val resolver = context.contentResolver
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, displayName)
                put(MediaStore.MediaColumns.MIME_TYPE, "text/html")
                put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS + "/" + FOLDER)
            }
            val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values) ?: return null
            return try {
                resolver.openOutputStream(uri)?.use { it.write(bytes) } ?: throw IOException("no output stream")
                uri
            } catch (e: Exception) {
                // Do not leave an empty entry behind in Downloads.
                try { resolver.delete(uri, null, null) } catch (_: Exception) { }
                null
            }
        }

        // Android 8-9: the public Downloads folder needs the legacy storage permission; without it
        // fall back to the app's own Downloads folder so the file is still saved.
        return try {
            writeTo(File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS), FOLDER), displayName, bytes)
        } catch (e: Exception) {
            try {
                writeTo(File(context.getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS), FOLDER), displayName, bytes)
            } catch (e2: Exception) {
                null
            }
        }
    }

    private fun writeTo(folder: File, name: String, bytes: ByteArray): Uri {
        if (!folder.exists() && !folder.mkdirs()) throw IOException("cannot create $folder")
        val file = File(folder, name)
        file.writeBytes(bytes)
        return Uri.fromFile(file)
    }
}
''')

