# ==============================================================================
# التتبع الديناميكي لزمن الاستجابة (Dynamic Latency Tracking)
#   - AiLatencyTracker: متوسط متحرك (80% قديم / 20% جديد) لزمن رد كل نموذج في SharedPreferences "ai_latency".
#   - providerOrder(): يرتّب النماذج من الأسرع للأبطأ؛ بلا بيانات => الترتيب الافتراضي (ChatGPT, Claude, Gemini).
#   - askProvider(): يقيس زمن الرد الناجح ويسجّله.
#   لا يحتاج تمرير Context إلى AiChatService (يُنشأ في 4 أماكن): الـ tracker يُهيَّأ مرة واحدة في VoiceAssistantApp
#   باستخدام applicationContext، تماماً مثل AiSettings.
# ==============================================================================
_LT_AI = _PKG + "/data/AiChatService.kt"

# 1) كائن التتبع + دالة recordLatency
_replace_once(
    _LT_AI,
    'class AiChatService(private val memoryManager: MemoryManager? = null) {',
    r'''/**
 * Moving average of the response time (ms) of each AI model, kept in SharedPreferences "ai_latency".
 * Initialised once in VoiceAssistantApp.onCreate (applicationContext), so AiChatService needs no Context.
 */
object AiLatencyTracker {
    private const val FILE = "ai_latency"

    /** Returned for a model that has no recorded time yet (so it sorts last). */
    const val UNKNOWN: Long = 999999L

    @Volatile
    private var prefs: android.content.SharedPreferences? = null

    fun init(context: android.content.Context) {
        if (prefs != null) return
        synchronized(this) {
            if (prefs == null) {
                prefs = context.applicationContext.getSharedPreferences(FILE, android.content.Context.MODE_PRIVATE)
            }
        }
    }

    fun average(provider: AiProvider): Long {
        val saved = prefs?.getLong(provider.name, 0L) ?: 0L
        return if (saved > 0L) saved else UNKNOWN
    }

    fun record(provider: AiProvider, timeMs: Long) {
        val p = prefs ?: return
        synchronized(this) {
            val oldAvg = p.getLong(provider.name, 0L)
            // متوسط متحرك (80% للقيم القديمة، 20% للقيمة الجديدة) لتجاهل التقلبات المؤقتة
            val newAvg = if (oldAvg == 0L) timeMs else (oldAvg * 0.8 + timeMs * 0.2).toLong()
            p.edit().putLong(provider.name, newAvg.coerceAtLeast(1L)).apply()
        }
    }
}

class AiChatService(private val memoryManager: MemoryManager? = null) {

    private fun recordLatency(provider: AiProvider, timeMs: Long) {
        AiLatencyTracker.record(provider, timeMs)
    }
'''
)

# 2) providerOrder(): ترتيب حسب السرعة المحفوظة
_replace_once(
    _LT_AI,
    '''        val selected = AiSettings.selectedProvider()
        val order = if (AiSettings.fallbackEnabled()) {
            listOf(selected) + AiProvider.values().filter { it != selected }
        } else {
            listOf(selected)
        }
        return order.filter { AiSettings.apiKey(it).isNotBlank() }''',
    r'''        // التبديل التلقائي مُعطّل: نلتزم بالنموذج الذي اختاره المستخدم فقط.
        if (!AiSettings.fallbackEnabled()) {
            return listOf(AiSettings.selectedProvider()).filter { AiSettings.apiKey(it).isNotBlank() }
        }
        // الترتيب الافتراضي (ChatGPT, Claude, Gemini) ثم الأسرع فعلياً أولاً.
        // sortedBy مستقر: النماذج التي بلا زمن محفوظ (999999) تبقى في آخر القائمة بترتيبها الافتراضي.
        return listOf(AiProvider.OPENAI, AiProvider.CLAUDE, AiProvider.GEMINI)
            .filter { AiSettings.apiKey(it).isNotBlank() }
            .sortedBy { AiLatencyTracker.average(it) }'''
)

