# 2. RoutineScheduler.kt: الجدولة عبر AlarmManager (تعمل والتطبيق مغلق)
write_file(_PKG + "/service/RoutineScheduler.kt", r'''package com.zevorix.assistant.service

import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import java.util.Calendar

/** Schedules one routine command at a clock time ("08:00"); the next occurrence of that time is used. */
object RoutineScheduler {
    const val ACTION_ROUTINE_STEP = "com.zevorix.assistant.action.ROUTINE_STEP"
    const val EXTRA_COMMAND = "routine_command"
    const val EXTRA_TIME = "routine_time"
    const val EXTRA_NOTIF_ID = "routine_notif_id"

    /** Same command at the same time -> same alarm (rescheduling replaces it); different times never collide. */
    fun requestCode(command: String, time: String): Int = ("$command@$time").hashCode()

    /** @return false if [timeStr] is not a valid HH:mm time or the alarm could not be set. */
    fun schedule(context: Context, command: String, timeStr: String): Boolean {
        val parts = timeStr.trim().split(":")
        if (parts.size != 2) return false
        val hour = parts[0].trim().toIntOrNull() ?: return false
        val minute = parts[1].trim().toIntOrNull() ?: return false
        if (hour !in 0..23 || minute !in 0..59) return false

        val cal = Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, hour)
            set(Calendar.MINUTE, minute)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
            if (timeInMillis <= System.currentTimeMillis()) {
                add(Calendar.DAY_OF_YEAR, 1)
            }
        }

        val app = context.applicationContext
        val intent = Intent(app, RoutineReceiver::class.java).apply {
            action = ACTION_ROUTINE_STEP
            putExtra(EXTRA_COMMAND, command)
            putExtra(EXTRA_TIME, timeStr.trim())
        }
        val pi = PendingIntent.getBroadcast(
            app,
            requestCode(command, timeStr.trim()),
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val am = app.getSystemService(AlarmManager::class.java) ?: return false
        return try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !am.canScheduleExactAlarms()) {
                am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, cal.timeInMillis, pi)
            } else {
                am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, cal.timeInMillis, pi)
            }
            true
        } catch (e: SecurityException) {
            // "Alarms & reminders" was revoked in the meantime -> inexact alarm instead.
            try {
                am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, cal.timeInMillis, pi)
                true
            } catch (e2: Exception) {
                false
            }
        }
    }
}
''')

# 3. RoutineReceiver.kt: عند حلول الوقت يفتح التطبيق لتنفيذ الأمر + إشعار احتياطي
#    (أندرويد 10+ قد يمنع فتح نشاط من الخلفية، لذلك يظهر إشعار يكفي الضغط عليه لتنفيذ الأمر)
write_file(_PKG + "/service/RoutineReceiver.kt", r'''package com.zevorix.assistant.service

import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.zevorix.assistant.MainActivity
import com.zevorix.assistant.viewmodel.AppLanguage

/** Fired by AlarmManager when a scheduled routine step is due. */
class RoutineReceiver : BroadcastReceiver() {

    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != RoutineScheduler.ACTION_ROUTINE_STEP) return
        val command = intent.getStringExtra(RoutineScheduler.EXTRA_COMMAND)?.takeIf { it.isNotBlank() } ?: return
        val notifId = 30000 + (command.hashCode() and 0x7FFF)

        val launch = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
            putExtra(MainActivity.EXTRA_ROUTINE_COMMAND, command)
            putExtra(RoutineScheduler.EXTRA_NOTIF_ID, notifId)
        }

        // Fallback first: tapping the notification runs the command even if Android blocks the direct launch.
        try {
            NotificationHelper.createChannels(context)
            val lang = AppLanguage.detect(command)
            val tap = PendingIntent.getActivity(
                context,
                notifId,
                launch,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            val notification = NotificationCompat.Builder(context, NotificationHelper.CHANNEL_REMINDERS)
                .setSmallIcon(android.R.drawable.ic_popup_reminder)
                .setContentTitle(lang.tr("أمر مجدول", "Scheduled command"))
                .setContentText(command)
                .setStyle(NotificationCompat.BigTextStyle().bigText(command))
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                .setCategory(NotificationCompat.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .setContentIntent(tap)
                .build()
            NotificationManagerCompat.from(context).notify(notifId, notification)
        } catch (e: Exception) {
            // Notification permission denied: only the direct launch below is possible.
        }

        try {
            context.startActivity(launch)
        } catch (e: Exception) {
            // Blocked from the background: the notification above is the way to run it.
        }
    }
}
''')

# 4. RoutineCommandBus.kt: قناة لا تُسقط الأمر إذا وصل قبل أن تبدأ الواجهة بالاستماع (بدء بارد)
write_file(_PKG + "/service/RoutineCommandBus.kt", r'''package com.zevorix.assistant.service

import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.receiveAsFlow

/** Carries a due routine command from MainActivity to MainViewModel. Buffered, each command is delivered once. */
object RoutineCommandBus {
    private val channel = Channel<String>(Channel.UNLIMITED)
    val events: Flow<String> = channel.receiveAsFlow()
    fun publish(command: String) {
        channel.trySend(command)
    }
}
''')

