# ==============================================================================
# مفتاح التوقيع الدائم (Release Keystore): يُقرأ من متغيرات البيئة فقط
#   KEYSTORE_PATH (افتراضي release.jks) / KEYSTORE_PASSWORD / KEY_ALIAS / KEY_PASSWORD
# ثبات التوقيع = ثبات هوية التطبيق (Device ID) بين البنايات => لا مشكلة LICENSE_BOUND.
# إن لم يوجد ملف المفتاح يرجع البناء إلى توقيع debug الافتراضي كما كان.
# ==============================================================================
_replace_once(
    "app/build.gradle.kts",
    r'''    buildTypes {
        release {
            isMinifyEnabled = false
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "../proguard-rules.pro"
            )
        }
    }
''',
    r'''    // ---- Release signing (env-driven) ---------------------------------------------
    // Note: no java.io.File here - inside android {} the name `java` is the Java plugin extension, so `java.io` fails to resolve.
    // file("x") in this script resolves against app/, while the CI step decodes the key
    // to app/release.jks and KEYSTORE_PATH may be "app/release.jks" (relative to the repo root).
    // So we try every sensible base and take the first file that really exists.
    val keystoreEnvPath: String = System.getenv("KEYSTORE_PATH") ?: "release.jks"
    val resolvedKeystore = listOf(
        file(keystoreEnvPath),                    // absolute path, or relative to app/
        rootProject.file(keystoreEnvPath),        // relative to the repo root
        file("release.jks"),                      // app/release.jks
        rootProject.file("app/release.jks")
    ).firstOrNull { it.exists() }
    val isCi: Boolean = System.getenv("CI") != null || System.getenv("GITHUB_ACTIONS") != null

    signingConfigs {
        create("release") {
            if (resolvedKeystore != null) {
                val ksPass = System.getenv("KEYSTORE_PASSWORD")
                val ksAlias = System.getenv("KEY_ALIAS")
                val keyPass = System.getenv("KEY_PASSWORD")
                if (ksPass.isNullOrEmpty() || ksAlias.isNullOrEmpty() || keyPass.isNullOrEmpty()) {
                    throw GradleException("Keystore found at " + resolvedKeystore.absolutePath +
                        " but KEYSTORE_PASSWORD / KEY_ALIAS / KEY_PASSWORD are not all set.")
                }
                storeFile = resolvedKeystore
                storePassword = ksPass
                keyAlias = ksAlias
                keyPassword = keyPass
            }
        }
    }

    // On CI an unsigned/debug-signed release must never go unnoticed.
    if (resolvedKeystore == null && isCi) {
        throw GradleException("Release keystore not found (KEYSTORE_PATH=" + keystoreEnvPath +
            "). Decode it to app/release.jks or set KEYSTORE_PATH correctly.")
    }

    buildTypes {
        release {
            isMinifyEnabled = false
            if (resolvedKeystore != null) {
                signingConfig = signingConfigs.getByName("release")
            } else {
                // Local build without a keystore: sign with the debug key so the APK is installable.
                signingConfig = signingConfigs.getByName("debug")
            }
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "../proguard-rules.pro"
            )
        }
        debug {
            if (resolvedKeystore != null) {
                signingConfig = signingConfigs.getByName("release")
            }
        }
    }
'''
)
print(">> Release keystore signing config (env-driven) applied.")


