# ---- 1) ThemePreference.kt (ملف جديد) ----
write_file(_PKG + "/ui/theme/ThemePreference.kt", r'''package com.zevorix.assistant.ui.theme

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

/**
 * The user's choice between the light and the dark theme.
 * Until the user picks one, the app simply follows the system setting.
 */
object ThemePreference {

    private const val PREFS_NAME = "theme_prefs"
    private const val KEY_DARK = "dark_mode"

    /** null = follow the system; true = dark; false = light. Observable by Compose. */
    var override: Boolean? by mutableStateOf(null)
        private set

    /** Loads the saved choice. Called once from the Application, before any screen is drawn. */
    fun init(context: Context) {
        val prefs = context.applicationContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        override = if (prefs.contains(KEY_DARK)) prefs.getBoolean(KEY_DARK, false) else null
    }

    /** The theme that must be shown now. */
    fun resolve(systemDark: Boolean): Boolean = override ?: systemDark

    /** Saves the user's choice and switches the whole app immediately. */
    fun set(context: Context, dark: Boolean) {
        context.applicationContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            .edit().putBoolean(KEY_DARK, dark).apply()
        override = dark
    }
}
''')

