# ---- 2) MemoryManager: بحث تقريبي بين الملفات المحفوظة فقط ----
insert_before(
    _fm_memory,
    "    fun clearAll() {",
    r'''    /**
     * Fuzzy search among the remembered files only (used by "افتح لي ملف X" / "open file X"):
     * an exact file-name match wins, otherwise the project sharing the most words with [query]
     * (at least half of them; the newest one wins ties). Returns null when nothing fits.
     */
    fun findProject(query: String): MemoryEntry? = synchronized(lock) {
        val wanted = TextNormalizer.key(query).trim()
        if (wanted.isEmpty()) return@synchronized null
        val projects = entries.filter { it.type == MemoryType.PROJECT }.sortedByDescending { it.lastUsedAt }

        val exact = projects.firstOrNull { p ->
            val name = TextNormalizer.key(p.metadata[META_FILE_NAME] ?: p.content)
            name == wanted || name.substringBeforeLast('.') == wanted
        }
        if (exact != null) return@synchronized exact

        val spoken = setOf("dot", "نقطه", "point")
        val words = wanted.split(NON_WORD)
            .map { if (it.startsWith("ال") && it.length > 4) it.substring(2) else it }
            .filter { it.length >= 2 && it !in STOP_WORDS && it !in spoken }
        if (words.isEmpty()) return@synchronized null

        var best: MemoryEntry? = null
        var bestScore = 0
        for (p in projects) {
            val haystack = TextNormalizer.key(p.metadata[META_FILE_NAME] ?: p.content)
            val score = words.count { haystack.contains(it) }
            if (score > bestScore) {
                best = p
                bestScore = score
            }
        }
        if (bestScore * 2 >= words.size) best else null
    }

''')

