insert_before(
    _fm_vm,
    "    /** Lists the last 3 projects with their last note and re-opens the newest one as the working file. */",
    r'''    /** "افتح لي ملف X" / "استرجع ملف X من الذاكرة" / "open file X": re-opens a remembered file as the working file. */
    private suspend fun openProjectFile(query: String?, lang: AppLanguage, speak: Boolean) {
        val projects = memoryManager.getProjects()
        if (projects.isEmpty()) {
            reply(
                lang.tr(
                    "لا توجد ملفات محفوظة في الذاكرة بعد. أرفق ملفاً أو قل «احفظ الملف» وسأتذكره.",
                    "There are no files in memory yet. Attach a file or say \"save the file\" and I'll remember it."
                ),
                lang,
                speak = speak
            )
            return
        }
        val wanted = query.orEmpty().trim()
        val target = if (wanted.isEmpty()) projects.first() else memoryManager.findProject(wanted)
        if (target == null) {
            val sb = StringBuilder(
                lang.tr(
                    "لم أجد في الذاكرة ملفاً باسم «$wanted».",
                    "I couldn't find a file named \"$wanted\" in memory."
                )
            )
            sb.append("\n\n").append(lang.tr("الملفات المحفوظة:", "Saved files:"))
            projects.take(MemoryManager.MAX_PROMPT_PROJECTS).forEach { sb.append('\n').append(memoryLabel(it)) }
            reply(sb.toString(), lang, speak = speak)
            return
        }
        val name = memoryLabel(target)
        val uri = target.metadata[MemoryManager.META_FILE_URI]
        val file = if (uri != null) withContext(Dispatchers.IO) { readProjectFile(name, uri) } else null
        if (file == null) {
            reply(
                lang.tr(
                    "وجدت الملف $name في الذاكرة لكن تعذّر فتحه. أرفقه مرة أخرى.",
                    "I found $name in memory but couldn't open it. Please attach it again."
                ),
                lang,
                speak = speak
            )
            return
        }
        ai.workingFile = file
        _uiState.update { it.copy(workingFileName = file.name) }
        memoryManager.updateProjectLastUsed(target.id)
        refreshMemoryState()
        reply(
            lang.tr(
                "فتحت الملف $name من الذاكرة وأصبح ملف العمل الحالي. ماذا تريد أن أفعل به؟",
                "I opened $name from memory and it's now the working file. What would you like me to do with it?"
            ),
            lang,
            speak = speak
        )
    }

    /** "احفظ الملف" / "احفظ التعديلات في الذاكرة" / "save the file": writes the working file and keeps it in memory. */
    private suspend fun saveWorkingFile(lang: AppLanguage, speak: Boolean) {
        val file = ai.workingFile
        if (file == null) {
            reply(
                lang.tr(
                    "لا يوجد ملف مفتوح لأحفظه. قل «افتح لي ملف» مع اسمه، أو أرفق ملفاً أولاً.",
                    "There's no open file to save. Say \"open file\" with its name, or attach a file first."
                ),
                lang,
                speak = speak
            )
            return
        }
        val savedUri = withContext(Dispatchers.IO) { writeWorkingFile(file) }
        if (savedUri == null) {
            reply(
                lang.tr(
                    "تعذّر حفظ الملف ${file.name}. جرّب زر «حفظ» في بطاقة الكود.",
                    "I couldn't save ${file.name}. Try the Save button on the code card."
                ),
                lang,
                speak = speak
            )
            return
        }
        val hadOriginal = file.uri != null
        if (savedUri != file.uri) ai.workingFile = file.copy(uri = savedUri)
        memoryManager.addProject(file.name, savedUri)
        refreshMemoryState()
        reply(
            if (hadOriginal) {
                lang.tr(
                    "تم حفظ التعديلات في الملف ${file.name} وتثبيته في الذاكرة.",
                    "Saved your changes to ${file.name} and kept it in memory."
                )
            } else {
                lang.tr(
                    "حفظت نسخة من الملف ${file.name} داخل التطبيق وسأتذكرها في الذاكرة.",
                    "I saved a copy of ${file.name} inside the app and will remember it in memory."
                )
            },
            lang,
            speak = speak
        )
    }

    /** Writes the file back to its own Uri, or into the app's private storage when it has none. Returns the Uri that holds it now. */
    private fun writeWorkingFile(file: com.zevorix.assistant.data.WorkingFile): String? {
        val bytes = file.content.toByteArray(Charsets.UTF_8)
        val original = file.uri
        return try {
            if (original != null) {
                val written = getApplication<Application>().contentResolver
                    .openOutputStream(android.net.Uri.parse(original), "wt")
                    ?.use { it.write(bytes) } != null
                if (written) original else null
            } else {
                val dir = File(getApplication<Application>().filesDir, "saved_files")
                if (!dir.exists() && !dir.mkdirs()) return null
                val safe = file.name.replace(Regex("[^\\p{L}\\p{N}._-]"), "_").take(80).ifBlank { "file.txt" }
                val target = File(dir, safe)
                target.writeBytes(bytes)
                android.net.Uri.fromFile(target).toString()
            }
        } catch (e: Exception) {
            null
        }
    }

''')


