# الفحص النهائي (يفشل بصوت عالٍ؛ لا يُطبع بيان الاكتمال إلا إذا نجحت كل البنود)
# ==============================================================================
def _fc_read(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()

def _fc_body(text, start_marker, end_markers):
    i = text.index(start_marker)
    ends = [text.index(m, i + len(start_marker)) for m in end_markers if m in text[i + len(start_marker):]]
    return text[i:min(ends)] if ends else text[i:]

def _fc(n, label, ok):
    print(">> CHECK {:>2}: {} {}".format(n, "OK  " if ok else "FAIL", label))
    if not ok:
        raise RuntimeError("Final check {} failed: {}".format(n, label))

_fc_lic = _fc_read(_FR_LIC)
_fc_ver = _fc_read(_FR_VER)
_fc_cred = _fc_read(_FR_CREDITS)
_fc_secret_hits = []
for _root, _dirs, _files in os.walk("."):
    _dirs[:] = [d for d in _dirs if d not in (".git", "build", ".gradle", "functions", "node_modules")]  # functions/ = backend server (may use LICENSE_SECRET)
    for _fn in _files:
        _fp = os.path.join(_root, _fn)
        if os.path.normpath(_fp) in ("index.js", "package.json", "package-lock.json"):
            continue  # root-level backend server files, not part of the APK
        if os.path.abspath(_fp) == os.path.abspath(__file__):
            continue  # the generator itself mentions the word in its own fix/check code
        try:
            if "LICENSE_SECRET" in _fc_read(_fp):
                _fc_secret_hits.append(_fp)
        except (UnicodeDecodeError, OSError):
            pass

for _h in _fc_secret_hits:
    print(">> LICENSE_SECRET found in:", _h)
    try:
        for _i, _ln in enumerate(_fc_read(_h).splitlines(), 1):
            if "LICENSE_SECRET" in _ln:
                print("     line {}: {}".format(_i, _ln.strip()[:160]))
    except Exception as _e:
        print("     (could not read lines: {})".format(_e))
if "LICENSE_SECRET" in KEY_ENV:
    print(">> LICENSE_SECRET is still present in KEY_ENV")
_fc(1, "no LICENSE_SECRET in KEY_ENV / gradle / build.yml / any generated file", "LICENSE_SECRET" not in KEY_ENV and not _fc_secret_hits)
