# ---- 2) AiChatService: askStream() تحت ask() ----
_replace_once(
    _ST_AI,
    r'''    suspend fun ask(text: String, lang: AppLanguage): AiResult = withContext(Dispatchers.IO) {
        callChat(text, lang, attachments = emptyList(), cost = 1)
    }
''',
    r'''    suspend fun ask(text: String, lang: AppLanguage): AiResult = withContext(Dispatchers.IO) {
        callChat(text, lang, attachments = emptyList(), cost = 1)
    }

    suspend fun askStream(text: String, lang: AppLanguage, onChunk: (String) -> Unit): AiResult = withContext(Dispatchers.IO) {
        val key = LicenseManager.getBackendKey()
        if (key.isEmpty()) return@withContext AiResult.Error(AiError.NOT_CONFIGURED, "no license")
        val did = CreditsManager.currentDeviceId()
        if (did.isEmpty()) return@withContext AiResult.Error(AiError.NOT_CONFIGURED, "no device id")

        val messages = ArrayList<Pair<String, String>>()
        synchronized(lock) { messages.addAll(history) }
        messages.add("user" to text)

        val providers = providerOrder().map { it.name.lowercase() }
        val body = JSONObject()
            .put("licenseKey", key)
            .put("deviceId", did)
            .put("provider", providers.firstOrNull() ?: "gemini")
            .put("providers", JSONArray(providers))
            .put("models", AiSettings.modelsJson())
            .put("systemPrompt", systemPrompt(lang))
            .put("cost", 1)
            .put("messages", JSONArray().apply {
                messages.forEach { (role, content) ->
                    val apiRole = if (role == "model") "assistant" else "user"
                    put(JSONObject().put("role", apiRole).put("content", content))
                }
            })

        try {
            val request = Request.Builder()
                .url("$BACKEND_BASE/api/ai/chat/stream")
                .post(body.toString().toRequestBody("application/json; charset=utf-8".toMediaType()))
                .build()

            client.newCall(request).execute().use { response ->
                if (!response.isSuccessful) {
                    return@use parseErrorResult(response.code, response.body?.string() ?: "")
                }
                val source = response.body?.source() ?: return@use AiResult.Error(AiError.EMPTY)
                val fullText = StringBuilder()

                while (!source.exhausted()) {
                    val line = source.readUtf8Line() ?: break
                    if (line.startsWith("data: ")) {
                        val data = line.substring(6)
                        if (data == "[DONE]") break
                        try {
                            val json = JSONObject(data)
                            if (json.has("error")) {
                                return@use AiResult.Error(AiError.OTHER, json.optString("error"))
                            }
                            val chunk = json.optString("text")
                            if (chunk.isNotEmpty()) {
                                fullText.append(chunk)
                                withContext(Dispatchers.Main) {
                                    onChunk(chunk) 
                                }
                            }
                        } catch (e: CancellationException) {
                            throw e
                        } catch (e: Exception) { }
                    }
                }
                
                val finalText = fullText.toString()
                lastRaw = finalText
                val (spoken, rawCode) = splitCode(finalText, lang)
                val code = applyEdit(rawCode)
                remember(text, finalText)
                AiResult.Success(spoken, code)
            }
        } catch (e: IOException) {
            // Buffering by a proxy (Render/Cloudflare) or a slow first token: fall back to non-streaming
            // so the user still gets an answer instead of a "connection error".
            android.util.Log.w("AiChat", "Stream failed (${e.message}); falling back to non-streaming")
            callChat(text, lang, attachments = emptyList(), cost = 1)
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            android.util.Log.w("AiChat", "Stream error (${e.message}); falling back to non-streaming")
            callChat(text, lang, attachments = emptyList(), cost = 1)
        }
    }
''',
)

# ---- 3) MainViewModel: askAi() يستبدل بالكامل بنسخة البث ----
_replace_once(
    _ST_VM,
    r'''    private suspend fun askAi(text: String, lang: AppLanguage, speak: Boolean = true) {
        if (!ensureQuota(lang, speak, 1)) return
        when (val result = ai.ask(text, lang)) {
            is AiResult.Success -> {
                reply(result.text, lang, result.code, speak = speak)
                CreditsManager.recordSuccess(1)
            }
            is AiResult.Error -> {
                // Configuration problems won't fix themselves, so stop the hands-free loop.
                if (result.kind == AiError.NOT_CONFIGURED || result.kind == AiError.BAD_KEY) {
                    conversationActive = false
                }
                replyAiError(result.kind, result.detail, lang, speak)
            }
        }
    }
''',
    r'''    private suspend fun askAi(text: String, lang: AppLanguage, speak: Boolean = true) {
        if (!ensureQuota(lang, speak)) return
        
        repository.addAssistantMessage("")
        _uiState.update { it.copy(status = AssistantStatus.PROCESSING, partialText = "") }
        
        var fullText = ""
        when (val result = ai.askStream(text, lang) { chunk ->
            fullText += chunk
            repository.updateLastMessage(fullText) 
        }) {
            is AiResult.Success -> {
                repository.updateLastMessage(result.text, result.code)
                CreditsManager.recordSuccess()
                if (speak && result.text.isNotBlank()) {
                    val speaking = tts.speak(result.text, lang.locale)
                    _uiState.update { it.copy(status = if (speaking) AssistantStatus.SPEAKING else AssistantStatus.IDLE) }
                    if (!speaking) scheduleAutoRestart()
                } else {
                    _uiState.update { it.copy(status = AssistantStatus.IDLE) }
                    if (speak) scheduleAutoRestart()
                }
            }
            is AiResult.Error -> {
                repository.updateLastMessage(aiErrorMessage(result.kind, lang))
                replyAiError(result.kind, result.detail, lang, speak)
            }
        }
    }
''',
)

