    r'''    /**
     * The answer for the screen: code blocks are removed (they appear in code cards) but Markdown is kept.
     * clean() strips * and # so the text can be read aloud, which is why the bubble needs this separate copy.
     * Returns null when nothing but code is left.
     */
    private fun displayText(full: String): String? {
        val text = if (full.contains("```") && Regex("```").findAll(full).count() % 2 == 1) full + "\n```" else full
        val withoutCode = if (text.contains("```")) fence.replace(text, " ") else text
        val shown = withoutCode.replace(Regex("\\n{3,}"), "\n\n").trim()
        return shown.ifBlank { null }
    }

    private fun applyEdit(blocks: List<CodeBlock>): List<CodeBlock> {''',
