write_file(_PKG + "/service/AssistantLauncher.kt", r'''package com.zevorix.assistant.service

import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import com.zevorix.assistant.MainActivity

/**
 * The launch used by the Quick Settings tile and the home-screen widget: open the assistant and start
 * listening at once (the same EXTRA_AUTO_LISTEN path the default-assistant gesture uses).
 */
object AssistantLauncher {
    const val REQUEST_TILE = 4101
    const val REQUEST_WIDGET = 4102

    fun intent(context: Context): Intent =
        Intent(context, MainActivity::class.java)
            .putExtra(MainActivity.EXTRA_AUTO_LISTEN, true)
            .addFlags(
                Intent.FLAG_ACTIVITY_NEW_TASK or
                    Intent.FLAG_ACTIVITY_CLEAR_TOP or
                    Intent.FLAG_ACTIVITY_SINGLE_TOP
            )

    fun pendingIntent(context: Context, requestCode: Int): PendingIntent =
        PendingIntent.getActivity(
            context,
            requestCode,
            intent(context),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
}
''')

write_file(_PKG + "/service/AssistantTileService.kt", r'''package com.zevorix.assistant.service

import android.os.Build
import android.service.quicksettings.Tile
import android.service.quicksettings.TileService
import com.zevorix.assistant.R

/** Quick Settings tile (notification shade): one tap opens the assistant and starts listening. */
class AssistantTileService : TileService() {

    override fun onStartListening() {
        super.onStartListening()
        val tile = qsTile ?: return
        tile.state = Tile.STATE_INACTIVE
        tile.label = getString(R.string.tile_label)
        if (Build.VERSION.SDK_INT >= 29) {
            tile.subtitle = getString(R.string.tile_subtitle)
        }
        tile.updateTile()
    }

    override fun onClick() {
        super.onClick()
        // The assistant can place calls and send messages, so a locked phone must be unlocked first.
        if (isLocked) {
            unlockAndRun { openAssistant() }
        } else {
            openAssistant()
        }
    }

    @Suppress("DEPRECATION")
    private fun openAssistant() {
        try {
            if (Build.VERSION.SDK_INT >= 34) {
                startActivityAndCollapse(AssistantLauncher.pendingIntent(this, AssistantLauncher.REQUEST_TILE))
            } else {
                startActivityAndCollapse(AssistantLauncher.intent(this))
            }
        } catch (_: Exception) {
            // Nothing else to do: the tile simply does not open the app.
        }
    }
}
''')

write_file(_PKG + "/service/AssistantWidgetProvider.kt", r'''package com.zevorix.assistant.service

import android.appwidget.AppWidgetManager
import android.appwidget.AppWidgetProvider
import android.content.Context
import android.widget.RemoteViews
import com.zevorix.assistant.R

/** Home-screen widget: a single button that opens the assistant and starts listening. */
class AssistantWidgetProvider : AppWidgetProvider() {

    override fun onUpdate(context: Context, appWidgetManager: AppWidgetManager, appWidgetIds: IntArray) {
        for (id in appWidgetIds) {
            appWidgetManager.updateAppWidget(id, buildViews(context))
        }
    }

    private fun buildViews(context: Context): RemoteViews =
        RemoteViews(context.packageName, R.layout.widget_assistant).apply {
            setOnClickPendingIntent(
                R.id.widget_root,
                AssistantLauncher.pendingIntent(context, AssistantLauncher.REQUEST_WIDGET)
            )
        }
}
''')

