write_file(_PKG + "/service/ShareBus.kt", r'''package com.zevorix.assistant.service

import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.provider.OpenableColumns
import android.webkit.MimeTypeMap
import com.zevorix.assistant.data.AttachmentData
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.receiveAsFlow
import java.io.ByteArrayOutputStream

/**
 * Carries what another app shared with the assistant ("Share" menu) from ShareReceiverActivity to MainViewModel.
 * Buffered, so an item shared while the app is starting is delivered once the screen is ready.
 */
object ShareBus {

    sealed class Shared {
        /** Plain text (a message, a link, an article, code...). */
        data class Text(val text: String, val subject: String?) : Shared()

        /** A picture, video, PDF or text/code file, with the caption the sender attached (if any). */
        data class Attachment(val data: AttachmentData, val caption: String?) : Shared()

        /** Something was shared but could not be read (blocked Uri, deleted file...). */
        object Failed : Shared()
    }

    /** Longest shared text sent to the AI; the rest is dropped. */
    const val MAX_TEXT_CHARS = 30_000

    private val channel = Channel<Shared>(Channel.UNLIMITED)
    val events: Flow<Shared> = channel.receiveAsFlow()

    fun publish(item: Shared) {
        channel.trySend(item)
    }

    /**
     * Reads the shared content of an ACTION_SEND intent. Blocking (reads the file): call it off the main thread
     * and while the receiving activity is still alive, because the Uri permission ends with that activity.
     * Returns null when the intent carries nothing usable.
     */
    fun read(context: Context, intent: Intent): Shared? {
        if (intent.action != Intent.ACTION_SEND) return null
        val text = intent.getCharSequenceExtra(Intent.EXTRA_TEXT)?.toString()?.trim().orEmpty()
        val subject = intent.getStringExtra(Intent.EXTRA_SUBJECT)?.trim()?.takeIf { it.isNotEmpty() }
        val uri = streamUri(intent)

        if (uri == null) {
            if (text.isEmpty()) return null
            return Shared.Text(text.take(MAX_TEXT_CHARS), subject)
        }

        // Only content:// Uris from other apps. file:// could point into this app's private storage, and this
        // app's own FileProvider must never be readable through a share from somewhere else.
        if (uri.scheme != "content" || uri.authority?.startsWith(context.packageName) == true) {
            return Shared.Failed
        }

        return try {
            val resolver = context.contentResolver
            var name = "shared_file"
            runCatching {
                resolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor ->
                    if (cursor.moveToFirst()) {
                        val index = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                        if (index >= 0) cursor.getString(index)?.takeIf { it.isNotBlank() }?.let { name = it }
                    }
                }
            }
            name = name.take(120)

            var mime = resolver.getType(uri) ?: intent.type ?: "application/octet-stream"
            if (mime == "application/octet-stream" || mime == "*/*") {
                val ext = name.substringAfterLast('.', "").lowercase()
                MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext)?.let { mime = it }
            }

            // Read at most one byte over the limit: enough for MainViewModel to say "too large" without loading it all.
            val limit = AttachmentData.MAX_BYTES + 1
            val out = ByteArrayOutputStream()
            val stream = resolver.openInputStream(uri) ?: return Shared.Failed
            stream.use { input ->
                val buffer = ByteArray(64 * 1024)
                while (out.size() < limit) {
                    val count = input.read(buffer, 0, minOf(buffer.size, limit - out.size()))
                    if (count < 0) break
                    out.write(buffer, 0, count)
                }
            }
            if (out.size() == 0) return Shared.Failed

            // uri = null on purpose: an edited shared file is saved in the app's own folder, never over the sender's file.
            Shared.Attachment(
                AttachmentData(name, mime, out.toByteArray(), null),
                text.take(MAX_TEXT_CHARS).ifEmpty { null }
            )
        } catch (e: Exception) {
            Shared.Failed
        }
    }

    @Suppress("DEPRECATION")
    private fun streamUri(intent: Intent): Uri? = try {
        if (Build.VERSION.SDK_INT >= 33) {
            intent.getParcelableExtra(Intent.EXTRA_STREAM, Uri::class.java)
        } else {
            intent.getParcelableExtra<Uri>(Intent.EXTRA_STREAM)
        }
    } catch (e: Exception) {
        null
    }
}
''')

write_file(_PKG + "/ShareReceiverActivity.kt", r'''package com.zevorix.assistant

import android.content.Intent
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.lifecycle.lifecycleScope
import com.zevorix.assistant.service.ShareBus
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * Target of the system "Share" menu. It has no screen: it reads the shared content right away (the permission to
 * read the sender's file ends when this activity finishes), hands it to ShareBus, then brings the one and only
 * MainActivity to the front, which lets MainViewModel answer it.
 */
class ShareReceiverActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val incoming = intent
        if (savedInstanceState != null || incoming == null || incoming.action != Intent.ACTION_SEND) {
            finish()
            return
        }
        lifecycleScope.launch {
            val shared = withContext(Dispatchers.IO) { ShareBus.read(applicationContext, incoming) }
            if (shared != null) ShareBus.publish(shared)
            startActivity(
                Intent(this@ShareReceiverActivity, MainActivity::class.java)
                    .putExtra(MainActivity.EXTRA_SHARE_LAUNCH, true)
                    .addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK or
                            Intent.FLAG_ACTIVITY_CLEAR_TOP or
                            Intent.FLAG_ACTIVITY_SINGLE_TOP
                    )
            )
            finish()
        }
    }
}
''')

