def _replace_between(path, start_marker, end_marker, new_text):
    """Replaces the text from `start_marker` (included) up to `end_marker` (excluded); both must be unique."""
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    if text.count(start_marker) != 1 or text.count(end_marker) != 1:
        raise RuntimeError("Expected unique markers in {}: {!r} / {!r}".format(path, start_marker[:60], end_marker[:60]))
    a = text.index(start_marker)
    b = text.index(end_marker)
    if b <= a:
        raise RuntimeError("Marker order is wrong in {}".format(path))
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text[:a] + new_text + text[b:])


