write_file(_PKG + "/speech/BargeInDetector.kt", r'''package com.zevorix.assistant.speech

import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import android.media.AudioFormat
import android.media.AudioRecord
import android.media.MediaRecorder
import android.media.audiofx.AcousticEchoCanceler
import android.media.audiofx.NoiseSuppressor
import android.os.Handler
import android.os.Looper
import android.os.SystemClock
import androidx.core.content.ContextCompat
import kotlin.math.max
import kotlin.math.sqrt

/**
 * Listens quietly while the assistant is talking and calls [onSpeech] (on the main thread) the moment the
 * user starts speaking over it. It never recognizes words: it only measures loudness, so it is cheap.
 *
 * To avoid reacting to the assistant's own voice coming out of the speaker:
 *  - the microphone source is VOICE_COMMUNICATION and the phone's echo canceller / noise suppressor are switched on;
 *  - the first moments are used to learn how loud the echo is, and the trigger level stays well above that;
 *  - the voice must stay clearly louder than the echo for several frames in a row (about 0.2 s).
 * The microphone is released BEFORE [onSpeech] runs, so the speech recognizer can take it right away.
 */
class BargeInDetector(context: Context, private val onSpeech: () -> Unit) {

    private val appContext = context.applicationContext
    private val main = Handler(Looper.getMainLooper())

    @Volatile
    private var generation = 0

    @Volatile
    private var running = false

    /** Starts watching (does nothing if already running or the microphone permission is missing). */
    @Synchronized
    fun start() {
        if (running) return
        if (ContextCompat.checkSelfPermission(appContext, Manifest.permission.RECORD_AUDIO) != PackageManager.PERMISSION_GRANTED) return
        running = true
        val gen = ++generation
        Thread({ watch(gen) }, "barge-in").apply { isDaemon = true }.start()
    }

    /** Stops watching; the microphone is released a few milliseconds later by the watcher thread itself. */
    @Synchronized
    fun stop() {
        generation++
        running = false
    }

    private fun isCurrent(gen: Int) = running && gen == generation

    private fun watch(gen: Int) {
        val rate = SAMPLE_RATE
        val minBuf = AudioRecord.getMinBufferSize(rate, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT)
        if (minBuf <= 0) {
            finish(gen, false)
            return
        }
        var record: AudioRecord? = null
        var echo: AcousticEchoCanceler? = null
        var noise: NoiseSuppressor? = null
        var triggered = false
        try {
            record = AudioRecord(
                MediaRecorder.AudioSource.VOICE_COMMUNICATION,
                rate,
                AudioFormat.CHANNEL_IN_MONO,
                AudioFormat.ENCODING_PCM_16BIT,
                max(minBuf, rate)
            )
            if (record.state != AudioRecord.STATE_INITIALIZED) {
                finish(gen, false)
                return
            }
            if (AcousticEchoCanceler.isAvailable()) {
                echo = AcousticEchoCanceler.create(record.audioSessionId)?.also { it.enabled = true }
            }
            if (NoiseSuppressor.isAvailable()) {
                noise = NoiseSuppressor.create(record.audioSessionId)?.also { it.enabled = true }
            }
            record.startRecording()

            val frame = ShortArray(rate / 50)   // 20 ms
            val startedAt = SystemClock.elapsedRealtime()
            var echoLevel = 0.0                  // peak-hold of the quiet part: the assistant's own voice
            var loudFrames = 0
            while (isCurrent(gen)) {
                val n = record.read(frame, 0, frame.size)
                if (n < 0) break
                if (n == 0) continue
                var sum = 0.0
                for (i in 0 until n) {
                    val v = frame[i].toDouble()
                    sum += v * v
                }
                val rms = sqrt(sum / n)
                val elapsed = SystemClock.elapsedRealtime() - startedAt
                if (elapsed > MAX_RUN_MS) break
                if (elapsed < LEARN_MS) {
                    // Learning the echo level: never triggers during this time.
                    echoLevel = max(rms, echoLevel * ECHO_DECAY)
                    continue
                }
                val threshold = max(MIN_RMS, echoLevel * ECHO_FACTOR)
                if (rms > threshold) {
                    loudFrames++
                    if (loudFrames >= NEED_FRAMES) {
                        triggered = true
                        break
                    }
                } else {
                    loudFrames = 0
                    echoLevel = max(rms, echoLevel * ECHO_DECAY)
                }
            }
        } catch (e: Exception) {
            triggered = false
        } finally {
            try { record?.stop() } catch (_: Exception) { }
            try { echo?.release() } catch (_: Exception) { }
            try { noise?.release() } catch (_: Exception) { }
            try { record?.release() } catch (_: Exception) { }
        }
        finish(gen, triggered)
    }

    private fun finish(gen: Int, triggered: Boolean) {
        val fire = triggered && isCurrent(gen)
        synchronized(this) {
            if (gen == generation) running = false
        }
        if (fire) main.post { onSpeech() }
    }

    private companion object {
        const val SAMPLE_RATE = 16000
        const val LEARN_MS = 600L
        const val MAX_RUN_MS = 120_000L
        const val MIN_RMS = 1500.0
        const val ECHO_FACTOR = 1.8
        const val ECHO_DECAY = 0.995
        const val NEED_FRAMES = 10
    }
}
''')

