_replace_once(
    _NF_HISTORY,
    '    private fun fileFor(id: Long) = File(dir, "$id.json")\n',
    r'''    /** Pins or unpins a chat. */
    @Synchronized
    fun setPinned(id: Long, pinned: Boolean) {
        val existing = readIndex()
        val result = JSONArray()
        for (i in 0 until existing.length()) {
            val item = existing.optJSONObject(i) ?: continue
            if (item.optLong("id") == id) item.put("pinned", pinned)
            result.put(item)
        }
        prefs.edit().putString(KEY_INDEX, result.toString()).apply()
    }

    private fun isPinned(index: JSONArray, id: Long): Boolean {
        for (i in 0 until index.length()) {
            val item = index.optJSONObject(i) ?: continue
            if (item.optLong("id") == id) return item.optBoolean("pinned", false)
        }
        return false
    }

    /**
     * Searches the titles, the messages and the code blocks of every saved chat (Arabic diacritics and
     * alef / yaa / taa-marbuta spelling variants are ignored). Run it on a background thread.
     * [keepGoing] lets the caller abort a search that is no longer needed.
     */
    fun search(query: String, keepGoing: () -> Boolean = { true }): List<SessionHit> {
        val q = normalizeWithMap(query.trim()).text
        if (q.isEmpty()) return emptyList()
        val hits = ArrayList<SessionHit>()
        for (session in getAllSessions()) {
            if (!keepGoing()) return hits
            var snippet: String? = null
            var found = normalizeWithMap(session.title).text.contains(q)
            for (m in loadMessages(session.id)) {
                val candidates = ArrayList<String>(1 + m.code.size)
                candidates.add(m.text)
                for (c in m.code) candidates.add(c.content)
                for (original in candidates) {
                    val norm = normalizeWithMap(original)
                    val at = norm.text.indexOf(q)
                    if (at < 0) continue
                    found = true
                    val o = norm.map[at]
                    val from = maxOf(0, o - 30)
                    val to = minOf(original.length, o + q.length + 70)
                    snippet = (if (from > 0) "…" else "") +
                        original.substring(from, to).replace('\n', ' ').trim() +
                        (if (to < original.length) "…" else "")
                    break
                }
                if (snippet != null) break
            }
            if (found) hits.add(SessionHit(session, snippet))
            if (hits.size >= 100) break
        }
        return hits
    }

    private class Normalized(val text: String, val map: IntArray)

    /** Lower-cases and unifies Arabic spellings; [Normalized.map] gives the original position of every kept character. */
    private fun normalizeWithMap(s: String): Normalized {
        val sb = StringBuilder(s.length)
        val map = IntArray(s.length)
        for (i in s.indices) {
            val c = s[i]
            if (c in '\u064B'..'\u065F' || c == '\u0640' || c == '\u0670') continue
            val n = when (c) {
                '\u0623', '\u0625', '\u0622', '\u0671' -> '\u0627'
                '\u0649' -> '\u064A'
                '\u0629' -> '\u0647'
                else -> c.lowercaseChar()
            }
            map[sb.length] = i
            sb.append(n)
        }
        return Normalized(sb.toString(), map.copyOf(sb.length))
    }

    private fun fileFor(id: Long) = File(dir, "$id.json")
''',
)

# ChatPdfExporter
write_file(_PKG + "/data/ChatPdfExporter.kt", r'''package com.zevorix.assistant.data

import android.content.ClipData
import android.content.Context
import android.content.Intent
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.Typeface
import android.graphics.pdf.PdfDocument
import android.text.Layout
import android.text.StaticLayout
import android.text.TextDirectionHeuristics
import android.text.TextPaint
import androidx.core.content.FileProvider
import com.zevorix.assistant.data.models.Message
import com.zevorix.assistant.viewmodel.AppLanguage
import java.io.File
import java.io.FileOutputStream
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Turns one conversation into a PDF (A4) with the phone's own text engine, so Arabic letters are joined and
 * right-to-left text is laid out correctly. Long messages and code blocks continue on the next page.
 * The file is written to <cache>/chat_exports and handed over with the share sheet.
 */
object ChatPdfExporter {

    private const val PAGE_W = 595
    private const val PAGE_H = 842
    private const val MARGIN = 40
    private const val CONTENT_W = PAGE_W - 2 * MARGIN

    private val USER_COLOR = 0xFF3F51B5.toInt()
    private val ASSISTANT_COLOR = 0xFF00796B.toInt()

    fun export(context: Context, title: String, messages: List<Message>, language: AppLanguage): File {
        val dir = File(context.cacheDir, "chat_exports").apply { mkdirs() }
        // Old exports are not needed any more: keep the folder small.
        val dayAgo = System.currentTimeMillis() - 24L * 60 * 60 * 1000
        dir.listFiles()?.forEach { if (it.lastModified() < dayAgo) it.delete() }

        val stamp = SimpleDateFormat("yyyyMMdd-HHmm", Locale.US).format(Date())
        val safeTitle = title.replace(Regex("[^\\p{L}\\p{N}]+"), "_").trim('_').take(30).ifEmpty { "chat" }
        val file = File(dir, "$safeTitle-$stamp.pdf")

        val titlePaint = TextPaint(Paint.ANTI_ALIAS_FLAG).apply {
            textSize = 20f; typeface = Typeface.DEFAULT_BOLD; color = 0xFF111111.toInt()
        }
        val metaPaint = TextPaint(Paint.ANTI_ALIAS_FLAG).apply { textSize = 10f; color = 0xFF666666.toInt() }
        val bodyPaint = TextPaint(Paint.ANTI_ALIAS_FLAG).apply { textSize = 12f; color = 0xFF1B1B1B.toInt() }
        val codePaint = TextPaint(Paint.ANTI_ALIAS_FLAG).apply {
            textSize = 9.5f; typeface = Typeface.MONOSPACE; color = 0xFF202020.toInt()
        }
        val dateFormat = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.US)

        val doc = PdfDocument()
        val writer = PageWriter(doc)
        try {
            writer.drawLayout(layout(title, titlePaint, CONTENT_W, rtlAware = true), MARGIN.toFloat())
            val shown = messages.count { !it.isPlaceholder }
            writer.drawLayout(
                layout(
                    language.tr("Zevorix · ${dateFormat.format(Date())} · $shown رسالة", "Zevorix · ${dateFormat.format(Date())} · $shown messages"),
                    metaPaint, CONTENT_W, rtlAware = true
                ),
                MARGIN.toFloat()
            )
            writer.space(12f)

            for (m in messages) {
                if (m.isPlaceholder) continue
                val who = if (m.isUser) language.tr("أنت", "You") else language.tr("المساعد", "Assistant")
                val headPaint = TextPaint(Paint.ANTI_ALIAS_FLAG).apply {
                    textSize = 11f; typeface = Typeface.DEFAULT_BOLD; color = if (m.isUser) USER_COLOR else ASSISTANT_COLOR
                }
                writer.drawLayout(
                    layout("$who · ${dateFormat.format(Date(m.timestamp))}", headPaint, CONTENT_W, rtlAware = true),
                    MARGIN.toFloat()
                )
                writer.space(2f)

                val body = cleanMarkdown(m.text)
                if (body.isNotBlank()) {
                    writer.drawLayout(layout(body, bodyPaint, CONTENT_W, rtlAware = true), MARGIN.toFloat())
                }
                val attachments = ArrayList<String>(3)
                if (m.imagePath != null) attachments.add(language.tr("[صورة]", "[Image]"))
                if (m.videoUrl != null) attachments.add(language.tr("[فيديو]", "[Video]"))
                if (m.audioUrl != null) attachments.add(language.tr("[موسيقى]", "[Music]"))
                if (attachments.isNotEmpty()) {
                    writer.drawLayout(layout(attachments.joinToString("  "), metaPaint, CONTENT_W, rtlAware = true), MARGIN.toFloat())
                }
                for (c in m.code) {
                    writer.space(4f)
                    val label = (c.fileName ?: c.language).ifBlank { "code" }
                    writer.drawLayout(layout(label, metaPaint, CONTENT_W, rtlAware = false), MARGIN.toFloat())
                    val code = c.content.replace("\t", "    ").take(60_000)
                    writer.drawLayout(
                        layout(code, codePaint, CONTENT_W - 12, rtlAware = false),
                        (MARGIN + 6).toFloat(),
                        background = 0xFFF1F3F4.toInt()
                    )
                }
                writer.space(14f)
            }
            writer.finish()
            FileOutputStream(file).use { doc.writeTo(it) }
        } finally {
            doc.close()
        }
        return file
    }

    /** Opens the share sheet for the PDF (the user can save it to Files / Drive or send it). */
    fun share(context: Context, file: File, language: AppLanguage) {
        val uri = FileProvider.getUriForFile(context, context.packageName + ".fileprovider", file)
        val send = Intent(Intent.ACTION_SEND).apply {
            type = "application/pdf"
            putExtra(Intent.EXTRA_STREAM, uri)
            clipData = ClipData.newRawUri(file.name, uri)
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        val chooser = Intent.createChooser(send, language.tr("تصدير المحادثة PDF", "Export chat as PDF")).apply {
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        context.startActivity(chooser)
    }

    private fun layout(text: String, paint: TextPaint, width: Int, rtlAware: Boolean): StaticLayout =
        StaticLayout.Builder.obtain(text, 0, text.length, paint, width)
            .setAlignment(Layout.Alignment.ALIGN_NORMAL)
            .setTextDirection(if (rtlAware) TextDirectionHeuristics.FIRSTSTRONG_LTR else TextDirectionHeuristics.LTR)
            .setLineSpacing(2f, 1f)
            .setIncludePad(false)
            .build()

    /** Light cleanup of the Markdown symbols so the PDF reads like text. */
    private fun cleanMarkdown(text: String): String =
        text.replace(Regex("(?m)^\\s{0,3}#{1,6}\\s*"), "")
            .replace("**", "")
            .replace("__", "")
            .replace("`", "")
            .trim()

    /** Draws layouts from top to bottom and starts a new page when the current one is full. */
    private class PageWriter(private val doc: PdfDocument) {
        private var pageNumber = 0
        private var page: PdfDocument.Page? = null
        private var canvas: Canvas? = null
        private var y = MARGIN.toFloat()
        private val footerPaint = TextPaint(Paint.ANTI_ALIAS_FLAG).apply { textSize = 9f; color = 0xFF888888.toInt() }
        private val bgPaint = Paint().apply { style = Paint.Style.FILL }

        private fun newPage() {
            finish()
            pageNumber++
            val started = doc.startPage(PdfDocument.PageInfo.Builder(PAGE_W, PAGE_H, pageNumber).create())
            page = started
            canvas = started.canvas
            y = MARGIN.toFloat()
        }

        fun finish() {
            val p = page ?: return
            canvas?.drawText("Zevorix · $pageNumber", (PAGE_W / 2f) - 24f, PAGE_H - 18f, footerPaint)
            doc.finishPage(p)
            page = null
            canvas = null
        }

        fun space(height: Float) {
            if (page == null) return
            y += height
        }

        fun drawLayout(layout: StaticLayout, x: Float, background: Int? = null) {
            if (layout.lineCount == 0) return
            var line = 0
            while (line < layout.lineCount) {
                if (page == null) newPage()
                val available = PAGE_H - MARGIN - y
                val top = layout.getLineTop(line)
                var end = line
                while (end < layout.lineCount && layout.getLineBottom(end) - top <= available) end++
                if (end == line) {
                    // Not even one line fits here: use a fresh page (or force the line if the page is already fresh).
                    if (y > MARGIN + 1f) {
                        newPage()
                        continue
                    }
                    end = line + 1
                }
                val bottom = layout.getLineBottom(end - 1)
                val c = canvas ?: return
                if (background != null) {
                    bgPaint.color = background
                    c.drawRect(x - 4f, y, x + layout.width + 4f, y + (bottom - top), bgPaint)
                }
                c.save()
                c.translate(x, y - top)
                c.clipRect(0f, top.toFloat(), layout.width.toFloat(), bottom.toFloat())
                layout.draw(c)
                c.restore()
                y += (bottom - top)
                line = end
                if (line < layout.lineCount) newPage()
            }
        }
    }
}
''')

