def _z_replace_region(rel, start, end, new, required=True):
    value = _z_read(rel)
    a = value.find(start)
    b = value.find(end, a + len(start)) if a >= 0 else -1
    if a < 0 or b < 0:
        if required:
            raise RuntimeError("Play payments: region not found in " + rel + " starting " + start[:80])
        return
    _z_write(rel, value[:a] + new + value[b:])

