_z_write(_Z_PKG + "/speech/AudioPermissionHandler.kt", r'''package com.zevorix.assistant.speech

import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalContext
import androidx.core.content.ContextCompat
import com.zevorix.assistant.service.ProactiveScheduler
import com.zevorix.assistant.ui.components.DisclosureKind
import com.zevorix.assistant.ui.components.rememberDisclosedPermissionRequest

object AudioPermissionHandler {
    const val PERMISSION = Manifest.permission.RECORD_AUDIO

    fun hasPermission(context: Context): Boolean =
        ContextCompat.checkSelfPermission(context, PERMISSION) == PackageManager.PERMISSION_GRANTED
}

/**
 * Returns a function that makes sure RECORD_AUDIO is granted.
 * If it already is, [onGranted] runs immediately; otherwise the prominent disclosure dialog is shown first
 * and the system permission dialog only appears after the user taps "Continue".
 */
@Composable
fun rememberAudioPermissionRequest(
    onGranted: () -> Unit,
    onDenied: () -> Unit = {}
): () -> Unit {
    val context = LocalContext.current
    return rememberDisclosedPermissionRequest(
        kind = DisclosureKind.MICROPHONE,
        language = ProactiveScheduler.language(context),
        permission = AudioPermissionHandler.PERMISSION,
        onGranted = onGranted,
        onDenied = onDenied
    )
}
''')

