# المرحلة الأخيرة (2): LicenseManager بدون أي إدخال كود يدوي (سياسة Google Play للمدفوعات)
#   - حُذفت redeem / history / RedeemResult وكل منطق القفل والمحاولات الفاشلة.
#   - بقيت: grantLifetime(code) (بعد شراء Play عبر الخادم)، grantLifetimeDebug()،
#     getBackendKey()/hasBackendKey()، حالة الاشتراك، وتوكن الشراء المعلّق.
# ==============================================================================
write_file(_PKG + "/data/LicenseManager.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.content.SharedPreferences
import android.util.Log

/**
 * إدارة الترخيص (بدون إدخال كود يدوي من المستخدم — التزاماً بسياسة Google Play للمدفوعات):
 *  - الترخيص الدائم يُمنح فقط بعد شراء Google Play، عبر كود موقّع يصدره الخادم (/api/play/credits).
 *  - الاشتراك يُكتب من BillingManager بعد التحقق من Play.
 *  - التوقيع: Ed25519 (LicenseVerifier).
 */
object LicenseManager {

    private const val TAG = "LicenseManager"
    private const val PREFS = "license_prefs"
    private const val KEY_LIFETIME = "lifetime"
    private const val KEY_SUB_ACTIVE = "sub_active"
    private const val KEY_SUB_EXPIRY = "sub_expiry"
    private const val KEY_BACKEND_CODE = "saved_backend_code"
    private const val KEY_PENDING_PLAY_TOKEN = "pending_play_purchase_token"

    private val lock = Any()
    private var prefs: SharedPreferences? = null

    fun init(context: Context) {
        synchronized(lock) {
            if (prefs == null) {
                prefs = context.applicationContext
                    .getSharedPreferences(PREFS, Context.MODE_PRIVATE)
            }
        }
    }

    fun hasLifetime(): Boolean = prefs?.getBoolean(KEY_LIFETIME, false) ?: false

    fun subscriptionActive(): Boolean {
        val p = prefs ?: return false
        if (!p.getBoolean(KEY_SUB_ACTIVE, false)) return false
        val expiry = p.getLong(KEY_SUB_EXPIRY, 0L)
        return expiry == 0L || expiry > System.currentTimeMillis()
    }

    fun isUnlocked(): Boolean = hasLifetime() || subscriptionActive()

    fun setSubscription(active: Boolean, expiryMillis: Long = 0L) {
        if (active && expiryMillis <= 0L) {
            Log.w(TAG, "setSubscription(active=true) ignored: expiryMillis must be > 0")
            return
        }
        synchronized(lock) {
            prefs?.edit()
                ?.putBoolean(KEY_SUB_ACTIVE, active)
                ?.putLong(KEY_SUB_EXPIRY, if (active) expiryMillis else 0L)
                ?.apply()
        }
        CreditsManager.refresh()
    }

    fun getBackendKey(): String {
        if (!isUnlocked()) return ""
        val saved = prefs?.getString(KEY_BACKEND_CODE, "") ?: ""
        return if (saved.isNotBlank()) saved else ""
    }

    fun hasBackendKey(): Boolean = getBackendKey().isNotEmpty()

    fun grantLifetime(code: String): Boolean {
        val normalized = LicenseVerifier.normalize(code)
        if (!LicenseVerifier.verify(normalized)) return false
        synchronized(lock) {
            val p = prefs ?: return false
            p.edit()
                .putBoolean(KEY_LIFETIME, true)
                .putString(KEY_BACKEND_CODE, normalized)
                .apply()
        }
        CreditsManager.refresh()
        return true
    }

    fun grantLifetimeDebug() {
        if (!com.zevorix.assistant.BuildConfig.DEBUG) return
        synchronized(lock) {
            prefs?.edit()?.putBoolean(KEY_LIFETIME, true)?.apply()
        }
        CreditsManager.refresh()
    }

    fun pendingPlayToken(): String = prefs?.getString(KEY_PENDING_PLAY_TOKEN, "") ?: ""

    fun savePendingPlayToken(token: String) {
        synchronized(lock) {
            prefs?.edit()?.putString(KEY_PENDING_PLAY_TOKEN, token)?.apply()
        }
    }

    fun clearPendingPlayToken() {
        synchronized(lock) {
            prefs?.edit()?.remove(KEY_PENDING_PLAY_TOKEN)?.apply()
        }
    }
}
''')

