# ==============================================================================
# Video from IMAGE and/or AUDIO (+ text): extra buttons in the "Generate video or music" dialog.
# Nothing else is changed: text-to-video, video edit and music keep working exactly as before.
# Server contract:  POST {VIDEO_SERVER_URL with generate-video -> generate-video-ref}  (multipart)
#   fields: prompt, licenseKey, deviceId, model, image (optional file), audio (optional file)
# ==============================================================================
_REF_PKG = "app/src/main/java/com/zevorix/assistant"

def _ref_once(rel, old, new):
    with open(rel, "r", encoding="utf-8") as _f:
        _t = _f.read()
    if new in _t:
        print(">> (skip) {} already has the image/audio video block".format(rel))
        return
    if _t.count(old) != 1:
        raise RuntimeError("Image/audio video: expected exactly one anchor in {}: {}".format(rel, old[:80]))
    with open(rel, "w", encoding="utf-8", newline="\n") as _f:
        _f.write(_t.replace(old, new))

# ---- 1) New file: holds the picked image / audio until the message is sent ----
write_file(_REF_PKG + "/data/VideoRefBridge.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.net.Uri
import android.provider.OpenableColumns
import java.io.File

/** Image / audio chosen in the "Generate video" dialog; MainViewModel takes them when the request is sent. */
object VideoRefBridge {
    const val MAX_IMAGE_BYTES: Long = 15L * 1024 * 1024
    const val MAX_AUDIO_BYTES: Long = 30L * 1024 * 1024

    @Volatile private var image: File? = null
    @Volatile private var audio: File? = null

    fun importImage(context: Context, uri: Uri): File? = importPicked(context, uri, "image/", MAX_IMAGE_BYTES, "ref_image")
    fun importAudio(context: Context, uri: Uri): File? = importPicked(context, uri, "audio/", MAX_AUDIO_BYTES, "ref_audio")

    fun setImage(file: File) { val old = image; image = file; if (old != null && old != file) old.delete() }
    fun setAudio(file: File) { val old = audio; audio = file; if (old != null && old != file) old.delete() }
    fun clearImage() { image?.delete(); image = null }
    fun clearAudio() { audio?.delete(); audio = null }
    fun takeImage(): File? { val f = image; image = null; return f }
    fun takeAudio(): File? { val f = audio; audio = null; return f }

    fun mimeFor(file: File): String = when (file.extension.lowercase()) {
        "png" -> "image/png"
        "webp" -> "image/webp"
        "jpg", "jpeg" -> "image/jpeg"
        "mp3" -> "audio/mpeg"
        "wav" -> "audio/wav"
        "ogg" -> "audio/ogg"
        "aac" -> "audio/aac"
        "flac" -> "audio/flac"
        "m4a" -> "audio/mp4"
        else -> "application/octet-stream"
    }

    private fun extensionFor(mime: String): String = when (mime) {
        "image/png" -> "png"
        "image/webp" -> "webp"
        "image/jpeg" -> "jpg"
        "audio/mpeg", "audio/mp3" -> "mp3"
        "audio/wav", "audio/x-wav", "audio/wave" -> "wav"
        "audio/ogg" -> "ogg"
        "audio/aac" -> "aac"
        "audio/flac" -> "flac"
        "audio/mp4", "audio/x-m4a", "audio/m4a" -> "m4a"
        else -> if (mime.startsWith("image/")) "jpg" else "mp3"
    }

    /** Copies the picked file into the app cache. Returns null if it has the wrong type, is too big or unreadable. */
    private fun importPicked(context: Context, uri: Uri, prefix: String, maxBytes: Long, name: String): File? {
        return try {
            val resolver = context.contentResolver
            val mime = resolver.getType(uri).orEmpty()
            if (mime.isNotEmpty() && !mime.startsWith(prefix)) return null

            var declared = -1L
            resolver.query(uri, null, null, null, null)?.use { cursor ->
                val index = cursor.getColumnIndex(OpenableColumns.SIZE)
                if (cursor.moveToFirst() && index >= 0 && !cursor.isNull(index)) declared = cursor.getLong(index)
            }
            if (declared > maxBytes) return null

            val folder = File(context.cacheDir, "video_refs").apply { mkdirs() }
            val target = File(folder, name + "_" + System.currentTimeMillis() + "." + extensionFor(mime))
            val input = resolver.openInputStream(uri) ?: return null
            var copied = 0L
            input.use { source ->
                target.outputStream().use { out ->
                    val buffer = ByteArray(64 * 1024)
                    while (true) {
                        val read = source.read(buffer)
                        if (read < 0) break
                        copied += read
                        if (copied > maxBytes) break
                        out.write(buffer, 0, read)
                    }
                }
            }
            if (copied <= 0L || copied > maxBytes) { target.delete(); null } else target
        } catch (e: Exception) {
            null
        }
    }
}
''')

