# تسريع الرد الصوتي (الصوت البشري): تقطيع الرد إلى جمل قصيرة؛ تُجلب الجملة الأولى (قصيرة) وتُشغَّل فوراً
# بينما تُجلب الجمل التالية في الخلفية، بدل انتظار تحويل الرد كله إلى صوت قبل أن يبدأ الكلام.
# يجب أن يبقى هذا القسم في آخر الملف. لا يغيّر أي شيء آخر (نفس واجهة HumanVoicePlayer).
# ==============================================================================
write_file("app/src/main/java/com/zevorix/assistant/speech/HumanVoicePlayer.kt", r'''package com.zevorix.assistant.speech

import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioTrack
import android.os.Handler
import android.os.Looper
import android.util.Log
import com.zevorix.assistant.BuildConfig
import com.zevorix.assistant.data.CreditsManager
import com.zevorix.assistant.data.LicenseManager
import java.util.concurrent.TimeUnit
import okhttp3.Call
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject

/**
 * Human TTS voices via the Render backend (/api/ai/tts).
 * The backend holds the Gemini key, verifies the license, and rate-limits per license.
 * The APK holds no API key.
 */
class HumanVoicePlayer {

    private val main = Handler(Looper.getMainLooper())
    private val http = OkHttpClient.Builder()
        .connectTimeout(15, TimeUnit.SECONDS)
        .writeTimeout(20, TimeUnit.SECONDS)
        .readTimeout(60, TimeUnit.SECONDS)
        .build()

    private val lock = Any()
    @Volatile private var generation = 0
    @Volatile private var currentTrack: AudioTrack? = null
    private val calls = java.util.concurrent.CopyOnWriteArraySet<Call>()

    private val rawUrl = BuildConfig.VIDEO_SERVER_URL.trim()
    private val backendBase = (if (rawUrl.isBlank()) "https://voiceassistantfinal.onrender.com/api/generate-video"
        else if (rawUrl.startsWith("http://") || rawUrl.startsWith("https://")) rawUrl
        else "https://$rawUrl")
        .replace("/api/generate-video", "")
        .removeSuffix("/api")
        .trimEnd('/')

    private val cache = object : android.util.LruCache<String, ByteArray>(6 * 1024 * 1024) {
        override fun sizeOf(key: String, value: ByteArray): Int = value.size
    }

    fun speak(text: String, voiceId: String, alarm: Boolean, onStarted: () -> Unit, onFinished: (String) -> Unit) {
        val clean = prepareText(text)
        if (clean.isEmpty()) { main.post { onFinished("") }; return }
        val gen = synchronized(lock) { generation++; abortCurrent(); generation }
        // The text is cut into short pieces: the first (short) one is fetched and played at once,
        // while the next pieces are fetched in the background, so the voice starts after ~1 sentence instead of the whole reply.
        val chunks = splitChunks(clean)
        Thread {
            val pool = java.util.concurrent.Executors.newFixedThreadPool(PREFETCH)
            var track: AudioTrack? = null
            var idx = 0
            var failed = false
            try {
                val futures = arrayOfNulls<java.util.concurrent.Future<ByteArray?>>(chunks.size)
                fun submit(i: Int) {
                    if (i < chunks.size && futures[i] == null) {
                        futures[i] = pool.submit(java.util.concurrent.Callable<ByteArray?> {
                            if (gen == generation) fetchPcm(chunks[i], voiceId) else null
                        })
                    }
                }
                for (i in 0 until minOf(PREFETCH, chunks.size)) submit(i)
                var totalBytes = 0L
                while (idx < chunks.size) {
                    if (gen != generation) return@Thread
                    val pcm = try { futures[idx]?.get() } catch (e: Exception) { null }
                    if (gen != generation) return@Thread
                    if (pcm == null) { failed = true; break }
                    submit(idx + PREFETCH)
                    var t = track
                    if (t == null) {
                        t = createTrack(alarm)
                        track = t
                        currentTrack = t
                        t.play()
                        main.post { if (gen == generation) onStarted() }
                    }
                    var offset = 0
                    while (offset < pcm.size && gen == generation) {
                        val chunk = minOf(4800, pcm.size - offset)
                        val w = t.write(pcm, offset, chunk)
                        if (w <= 0) break
                        offset += w
                    }
                    totalBytes += offset
                    idx++
                }
                val t = track
                if (gen == generation && t != null) {
                    val frames = totalBytes / 2
                    val deadline = System.currentTimeMillis() + frames * 1000 / 24000 + 2000
                    while (gen == generation && System.currentTimeMillis() < deadline) {
                        val head = try { t.playbackHeadPosition.toLong() and 0xFFFFFFFFL } catch (e: Exception) { frames }
                        if (head >= frames) break
                        Thread.sleep(30)
                    }
                }
                // What could not be fetched (no connection / quota) is handed back to be said by the phone's voice.
                val remaining = if (failed) chunks.drop(idx).joinToString(" ") else ""
                main.post { if (gen == generation) onFinished(remaining) }
            } catch (e: Exception) {
                Log.e("HumanVoice", "playback failed", e)
                val remaining = chunks.drop(idx).joinToString(" ")
                main.post { if (gen == generation) onFinished(remaining) }
            } finally {
                pool.shutdownNow()
                val t = track
                if (t != null) {
                    try { t.stop() } catch (_: Exception) { }
                    t.release()
                    if (currentTrack === t) currentTrack = null
                }
            }
        }.apply { isDaemon = true }.start()
    }

    fun stop() {
        synchronized(lock) { generation++; abortCurrent() }
    }

    private fun abortCurrent() {
        calls.forEach { try { it.cancel() } catch (_: Exception) { } }
        calls.clear()
        currentTrack?.let {
            try { it.pause(); it.flush() } catch (_: Exception) { }
        }
    }

    private fun fetchPcm(text: String, voiceId: String): ByteArray? {
        val key = LicenseManager.getBackendKey()
        if (key.isEmpty()) return null
        val cacheKey = "$voiceId|$text"
        cache.get(cacheKey)?.let { return it }

        val body = JSONObject()
            .put("licenseKey", key)
            .put("deviceId", CreditsManager.currentDeviceId())
            .put("text", text)
            .put("voiceId", voiceId)
            .toString().toRequestBody("application/json; charset=utf-8".toMediaType())
        val request = Request.Builder().url("$backendBase/api/ai/tts").post(body).build()
        val call = http.newCall(request)
        calls.add(call)
        return try {
            call.execute().use { response ->
                if (!response.isSuccessful) {
                    Log.w("HumanVoice", "TTS HTTP ${response.code}")
                    return null
                }
                val bytes = response.body?.bytes() ?: return null
                if (bytes.isEmpty()) return null
                cache.put(cacheKey, bytes)
                bytes
            }
        } catch (e: Exception) {
            Log.w("HumanVoice", "TTS error: ${e.message}")
            null
        } finally {
            calls.remove(call)
        }
    }

    private fun createTrack(alarm: Boolean): AudioTrack {
        val minBuf = AudioTrack.getMinBufferSize(24000, AudioFormat.CHANNEL_OUT_MONO, AudioFormat.ENCODING_PCM_16BIT)
        return AudioTrack.Builder()
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(if (alarm) AudioAttributes.USAGE_ALARM else AudioAttributes.USAGE_ASSISTANT)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                    .build()
            )
            .setAudioFormat(
                AudioFormat.Builder()
                    .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                    .setSampleRate(24000)
                    .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                    .build()
            )
            .setBufferSizeInBytes(maxOf(minBuf, 24000 * 2))
            .setTransferMode(AudioTrack.MODE_STREAM)
            .build()
    }

    /** Short first piece (fast start), then longer pieces; never cuts inside a word unless a "word" is huge. */
    private fun splitChunks(text: String): List<String> {
        val pieces = ArrayList<String>()
        for (s in Regex("(?<=[.!?\\u061F\\u2026\\n])\\s+").split(text)) {
            var p = s.trim()
            while (p.length > NEXT_CHUNK) {
                var cut = p.lastIndexOf(' ', NEXT_CHUNK)
                if (cut < NEXT_CHUNK / 2) cut = NEXT_CHUNK
                pieces.add(p.substring(0, cut).trim())
                p = p.substring(cut).trim()
            }
            if (p.isNotEmpty()) pieces.add(p)
        }
        val out = ArrayList<String>()
        var cur = StringBuilder()
        for (p in pieces) {
            val limit = if (out.isEmpty()) FIRST_CHUNK else NEXT_CHUNK
            if (cur.isNotEmpty() && cur.length + 1 + p.length > limit) {
                out.add(cur.toString())
                cur = StringBuilder()
            }
            if (cur.isNotEmpty()) cur.append(' ')
            cur.append(p)
        }
        if (cur.isNotEmpty()) out.add(cur.toString())
        return out
    }

    private fun prepareText(raw: String): String {
        var t = raw.replace(Regex("```[\\s\\S]*?```"), " ")
        t = t.replace(Regex("`([^`]*)`")) { it.groupValues[1] }
        t = t.replace(Regex("https?://\\S+"), " ")
        t = t.replace(Regex("[*_#>~|=^\\[\\]{}\\\\]+"), " ")
        t = t.replace(Regex("[\\p{So}\\p{Cs}\\p{Cn}]"), " ")
        t = t.replace(Regex("[ \\t\\u00A0]+"), " ")
        return t.trim().take(2000)
    }
}

private const val FIRST_CHUNK = 110
private const val NEXT_CHUNK = 260
private const val PREFETCH = 2
''')

print(">> Faster voice replies: HumanVoicePlayer now speaks sentence by sentence (first sentence starts right away, next ones prefetched).")


