# 4) GemmaManager.kt
write_file(_GM_PKG + "/data/GemmaManager.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.OpenableColumns
import android.util.Log
import androidx.core.content.ContextCompat
import com.google.mediapipe.tasks.genai.llminference.LlmInference
import com.google.mediapipe.tasks.genai.llminference.LlmInferenceSession
import java.io.File
import java.io.IOException
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext

/**
 * Runs Gemma fully on the phone through the MediaPipe LLM Inference API.
 *
 * Typical use:
 *   1) GemmaManager.initialize(context)            // false when the model file is missing or fails to load
 *   2) GemmaManager.generate("...")                // Result<String>
 *   3) GemmaManager.release()                      // when the memory is needed elsewhere
 *
 * Where the model file is looked for (first hit wins):
 *   - app private storage:      filesDir/models/gemma-2b-it-cpu-int4.bin   (needs no permission, works on every Android)
 *   - app external storage:     Android/data/<package>/files/[models/]gemma-2b-it-cpu-int4.bin
 *   - shared storage folders:   "voice assistant 2" and Download  (readable only on Android 10 and lower,
 *                               or up to Android 12L with READ_EXTERNAL_STORAGE granted; newer versions block it)
 * On newer Android versions call importModel() with a Uri from the system file picker
 * (ActivityResultContracts.OpenDocument): it copies the file once into app private storage.
 *
 * Everything heavy runs off the main thread, and one Mutex serializes init / generate / release,
 * because the native engine is not safe for concurrent calls.
 */
object GemmaManager {

    const val MODEL_FILE_NAME = "gemma-2b-it-cpu-int4.bin"
    const val LEGACY_FOLDER_NAME = "voice assistant 2"
    const val READ_STORAGE_PERMISSION = "android.permission.READ_EXTERNAL_STORAGE"

    private const val TAG = "GemmaManager"

    // Input tokens + output tokens. The converted Gemma 2B file has a fixed KV-cache size, so keep this modest.
    private const val MAX_TOKENS = 1024
    private const val TOP_K = 40

    // Arabic needs many tokens per character: trim long prompts (the newest text is kept) instead of failing.
    private const val MAX_PROMPT_CHARS = 1800

    // A real Gemma 2B int4 file is more than 1 GB; anything tiny is a broken or partial copy.
    private const val MIN_MODEL_BYTES = 100L * 1024L * 1024L
    private const val EXTRA_FREE_BYTES = 64L * 1024L * 1024L
    private const val COPY_BUFFER_BYTES = 1024 * 1024

    sealed class State {
        object NotInitialized : State()
        object ModelMissing : State()
        object Loading : State()
        object Ready : State()
        class Error(val message: String) : State()
    }

    private val _state = MutableStateFlow<State>(State.NotInitialized)
    val state: StateFlow<State> = _state.asStateFlow()

    private val lock = Mutex()

    @Volatile
    private var engine: LlmInference? = null

    fun isReady(): Boolean = engine != null && _state.value === State.Ready

    // ------------------------------------------------------------------ model file

    /** The copy that importModel() creates; always readable by the app. */
    fun appModelFile(context: Context): File =
        File(File(context.applicationContext.filesDir, "models"), MODEL_FILE_NAME)

    private fun candidateFiles(context: Context): List<File> {
        val app = context.applicationContext
        val list = ArrayList<File>()
        list.add(appModelFile(app))
        val external = app.getExternalFilesDir(null)
        if (external != null) {
            list.add(File(File(external, "models"), MODEL_FILE_NAME))
            list.add(File(external, MODEL_FILE_NAME))
        }
        @Suppress("DEPRECATION")
        val shared = Environment.getExternalStorageDirectory()
        list.add(File(File(shared, LEGACY_FOLDER_NAME), MODEL_FILE_NAME))
        list.add(File(File(shared, "Download"), MODEL_FILE_NAME))
        return list
    }

    /** The first readable, plausibly complete model file, or null. */
    fun findModelFile(context: Context): File? =
        candidateFiles(context).firstOrNull { f ->
            try {
                f.isFile && f.canRead() && f.length() >= MIN_MODEL_BYTES
            } catch (e: SecurityException) {
                false
            }
        }

    fun isModelAvailable(context: Context): Boolean = findModelFile(context) != null

    /** True when the legacy shared-storage folders could be read after the user grants READ_EXTERNAL_STORAGE. */
    fun needsStoragePermissionRequest(context: Context): Boolean {
        if (Build.VERSION.SDK_INT > Build.VERSION_CODES.S_V2) return false
        return ContextCompat.checkSelfPermission(context, READ_STORAGE_PERMISSION) != PackageManager.PERMISSION_GRANTED
    }

    fun missingModelMessage(context: Context): String =
        "ملف النموذج $MODEL_FILE_NAME غير موجود. اختر الملف من التخزين ليُنسخ إلى التطبيق (" +
            appModelFile(context).absolutePath + ")."

    // ------------------------------------------------------------------ init / release

    /** Loads the model. Returns true when Gemma is ready; check [state] for the reason otherwise. */
    suspend fun initialize(context: Context): Boolean {
        val app = context.applicationContext
        return withContext(Dispatchers.IO) {
            lock.withLock { initLocked(app) }
        }
    }

    private fun initLocked(app: Context): Boolean {
        if (engine != null && _state.value === State.Ready) return true
        val file = findModelFile(app)
        if (file == null) {
            _state.value = State.ModelMissing
            return false
        }
        _state.value = State.Loading
        return try {
            closeEngineLocked()
            val options = LlmInference.LlmInferenceOptions.builder()
                .setModelPath(file.absolutePath)
                .setMaxTokens(MAX_TOKENS)
                .setMaxTopK(TOP_K)
                .build()
            engine = LlmInference.createFromOptions(app, options)
            _state.value = State.Ready
            true
        } catch (e: Throwable) {
            // Throwable on purpose: a missing native library or an out-of-memory error must not crash the app.
            Log.e(TAG, "Gemma init failed", e)
            engine = null
            _state.value = State.Error(e.message ?: e.javaClass.simpleName)
            false
        }
    }

    suspend fun release() {
        withContext(Dispatchers.IO) {
            lock.withLock { closeEngineLocked() }
        }
    }

    private fun closeEngineLocked() {
        val old = engine
        engine = null
        if (old != null) {
            try {
                old.close()
            } catch (e: Throwable) {
                Log.w(TAG, "Gemma close failed", e)
            }
        }
        if (_state.value === State.Ready) _state.value = State.NotInitialized
    }

    // ------------------------------------------------------------------ generation

    /**
     * One full reply. Each call uses a fresh session, so earlier requests never leak into this one
     * (put any history you want the model to see inside [prompt] or [systemPrompt]).
     * The call cannot be interrupted once the native generation has started.
     */
    suspend fun generate(prompt: String, systemPrompt: String? = null, temperature: Float = 0.7f): Result<String> {
        if (prompt.isBlank()) return Result.failure(IllegalArgumentException("النص فارغ."))
        val full = buildPrompt(prompt, systemPrompt)
        return withContext(Dispatchers.IO) {
            lock.withLock { generateLocked(full, temperature) }
        }
    }

    private fun generateLocked(prompt: String, temperature: Float): Result<String> {
        val llm = engine
            ?: return Result.failure(IllegalStateException("نموذج Gemma غير جاهز. استدعِ initialize() أولاً."))
        return try {
            val sessionOptions = LlmInferenceSession.LlmInferenceSessionOptions.builder()
                .setTopK(TOP_K)
                .setTemperature(temperature.coerceIn(0.1f, 1.5f))
                .setRandomSeed((System.nanoTime() and 0x7FFFFFFFL).toInt())
                .build()
            val raw = LlmInferenceSession.createFromOptions(llm, sessionOptions).use { session ->
                session.addQueryChunk(prompt)
                session.generateResponse()
            }
            val reply = cleanReply(raw)
            if (reply.isEmpty()) {
                Result.failure(IllegalStateException("أعاد النموذج رداً فارغاً."))
            } else {
                Result.success(reply)
            }
        } catch (e: Throwable) {
            Log.e(TAG, "Gemma generation failed", e)
            Result.failure(e)
        }
    }

    /** Gemma-it chat format. Gemma has no system role, so the system text is placed in front of the user text. */
    private fun buildPrompt(user: String, system: String?): String {
        val body = StringBuilder()
        if (!system.isNullOrBlank()) body.append(system.trim()).append("\n\n")
        body.append(user.trim())
        var text = body.toString()
        if (text.length > MAX_PROMPT_CHARS) text = text.takeLast(MAX_PROMPT_CHARS)
        return "<start_of_turn>user\n" + text + "<end_of_turn>\n<start_of_turn>model\n"
    }

    private fun cleanReply(raw: String): String =
        raw.replace("<end_of_turn>", "")
            .replace("<start_of_turn>", "")
            .replace("<eos>", "")
            .replace("<bos>", "")
            .trim()

    // ------------------------------------------------------------------ import from the file picker

    /**
     * Copies the model chosen in the system file picker into app private storage (one time, about 1.3 GB).
     * [onProgress] gets 0..100 from a background thread, and only when the file size is known.
     * A half-copied file is never left behind: it is written as .part and renamed only when complete.
     */
    suspend fun importModel(context: Context, source: Uri, onProgress: (Int) -> Unit = {}): Result<File> {
        val app = context.applicationContext
        return withContext(Dispatchers.IO) {
            val target = appModelFile(app)
            val dir = target.parentFile
            val part = File(dir, MODEL_FILE_NAME + ".part")
            try {
                if (dir == null || (!dir.exists() && !dir.mkdirs())) throw IOException("تعذّر إنشاء مجلد النموذج.")
                val total = querySize(app, source)
                if (total > 0 && dir.usableSpace < total + EXTRA_FREE_BYTES) {
                    throw IOException("المساحة الفارغة في الهاتف لا تكفي لنسخ النموذج.")
                }
                val input = app.contentResolver.openInputStream(source)
                    ?: throw IOException("تعذّر فتح الملف المحدد.")
                input.use { ins ->
                    part.outputStream().use { outs ->
                        val buffer = ByteArray(COPY_BUFFER_BYTES)
                        var copied = 0L
                        var lastPercent = -1
                        while (true) {
                            ensureActive()
                            val n = ins.read(buffer)
                            if (n < 0) break
                            outs.write(buffer, 0, n)
                            copied += n
                            if (total > 0) {
                                val percent = (copied * 100L / total).toInt()
                                if (percent != lastPercent) {
                                    lastPercent = percent
                                    onProgress(percent)
                                }
                            }
                        }
                        outs.flush()
                    }
                }
                if (part.length() < MIN_MODEL_BYTES) throw IOException("الملف المنسوخ صغير جداً ويبدو ناقصاً.")
                lock.withLock {
                    closeEngineLocked()
                    if (target.exists() && !target.delete()) throw IOException("تعذّر استبدال النموذج القديم.")
                    if (!part.renameTo(target)) throw IOException("تعذّر حفظ النموذج.")
                }
                Result.success(target)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Throwable) {
                Log.e(TAG, "Gemma import failed", e)
                Result.failure(e)
            } finally {
                if (part.exists()) part.delete()
            }
        }
    }

    private fun querySize(context: Context, uri: Uri): Long {
        return try {
            val cursor = context.contentResolver.query(uri, arrayOf(OpenableColumns.SIZE), null, null, null)
            cursor?.use { c ->
                if (c.moveToFirst()) {
                    val index = c.getColumnIndex(OpenableColumns.SIZE)
                    if (index >= 0 && !c.isNull(index)) c.getLong(index) else -1L
                } else {
                    -1L
                }
            } ?: -1L
        } catch (e: Exception) {
            -1L
        }
    }
}
''')

