write_file(_PKG + "/data/PaymentConfigManager.kt", r'''package com.zevorix.assistant.data

import android.content.Context
import android.util.Log
import com.google.firebase.FirebaseApp
import com.google.firebase.remoteconfig.FirebaseRemoteConfig
import com.google.firebase.remoteconfig.remoteConfigSettings
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow

object PaymentConfigManager {
    private var remoteConfig: FirebaseRemoteConfig? = null

    // القيمة الافتراضية: false (التطبيق مجاني للجميع)
    private val _isPaymentEnabled = MutableStateFlow(false)
    val isPaymentEnabled = _isPaymentEnabled.asStateFlow()

    fun init(context: Context) {
        try {
            // التحقق من تهيئة Firebase لتجنب الانهيار إذا كان google-services.json مفقوداً
            if (FirebaseApp.getApps(context).isEmpty()) {
                Log.w("RemoteConfig", "Firebase not initialized. App defaults to FREE mode.")
                return
            }
            remoteConfig = FirebaseRemoteConfig.getInstance()
            val configSettings = remoteConfigSettings {
                minimumFetchIntervalInSeconds = 10 // 10 ثوانٍ للتجربة السريعة
            }
            remoteConfig?.setConfigSettingsAsync(configSettings)

            remoteConfig?.setDefaultsAsync(mapOf(
                "is_payment_enabled" to false
            ))

            fetchConfig()
        } catch (e: Exception) {
            Log.e("RemoteConfig", "Failed to init", e)
        }
    }

    private fun fetchConfig() {
        remoteConfig?.fetchAndActivate()?.addOnCompleteListener { task ->
            if (task.isSuccessful) {
                _isPaymentEnabled.value = remoteConfig?.getBoolean("is_payment_enabled") ?: false
                Log.i("RemoteConfig", "Payment enabled = ${_isPaymentEnabled.value}")
                // تحديث واجهة التطبيق فوراً
                LicenseManager.refreshLicenseState()
                CreditsManager.refresh()
            }
        }
    }
}
''')

