# 3. مطابقة تقريبية للكلمة المفتاحية في الجمل القصيرة
_replace_once(
    _ww_path,
    "            return wakeRegexes.any { it.containsMatchIn(plain) }\n"
    "        }\n",
    r'''            if (wakeRegexes.any { it.containsMatchIn(plain) }) return true
            // The recognizer often drops "يا" or mis-spells the keyword: accept it alone in a SHORT utterance.
            val words = plain.split(' ').filter { it.isNotEmpty() }
            if (words.isEmpty() || words.size > 3) return false
            return words.any { isKeywordLike(it) }
        }

        // Normalized keywords (see normalize()): "مساعد", "assistant", "zevorix", "زيفوريكس".
        private val keywordTargets = listOf("مساعد", "assistant", "zevorix", "زيفوريكس")

        private fun isKeywordLike(word: String): Boolean {
            // Drop the Arabic definite article: "المساعد" -> "مساعد".
            val w = if (word.startsWith("ال") && word.length > 4) word.substring(2) else word
            if (w.length < 4) return false
            return keywordTargets.any { t ->
                val maxDistance = if (t.length >= 7) 2 else 1
                kotlin.math.abs(w.length - t.length) <= maxDistance && editDistance(w, t) <= maxDistance
            }
        }

        private fun editDistance(a: String, b: String): Int {
            var prev = IntArray(b.length + 1) { it }
            var cur = IntArray(b.length + 1)
            for (i in 1..a.length) {
                cur[0] = i
                for (j in 1..b.length) {
                    val cost = if (a[i - 1] == b[j - 1]) 0 else 1
                    cur[j] = minOf(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
                }
                val tmp = prev; prev = cur; cur = tmp
            }
            return prev[b.length]
        }
''',
)

