write_file(_PKG + "/ui/components/ThinkingSparkles.kt", r'''package com.zevorix.assistant.ui.components

import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.RepeatMode
import androidx.compose.animation.core.animateFloat
import androidx.compose.animation.core.infiniteRepeatable
import androidx.compose.animation.core.rememberInfiniteTransition
import androidx.compose.animation.core.tween
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.offset
import androidx.compose.foundation.layout.width
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.semantics.clearAndSetSemantics
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import kotlin.math.PI
import kotlin.math.sin

// الرموز الرياضية والنجوم
private val SPARK_SYMBOLS = listOf("✦", "π", "∑", "✧", "√", "∫", "✦", "≈", "x²", "✧", "∞", "Δ", "≠", "±", "÷", "✦")

/**
 * Stars and math symbols that float up and fade out while the assistant is "thinking".
 * Purely decorative (hidden from TalkBack); every frame is drawn in graphicsLayer, so nothing recomposes per frame.
 */
@Composable
fun ThinkingSparkles(modifier: Modifier = Modifier) {
    val transition = rememberInfiniteTransition(label = "thinkingSparkles")

    // سرعة تصاعد الرموز
    val progress = transition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis = 2500, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "thinkingSparklesProgress"
    )

    // نبض خفيف في الحجم
    val pulse = transition.animateFloat(
        initialValue = 0.8f,
        targetValue = 1.2f,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis = 800, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "thinkingPulse"
    )

    val density = LocalDensity.current.density
    val riseDp = 50f
    val widthDp = 180f
    val colorA = MaterialTheme.colorScheme.primary
    val colorB = MaterialTheme.colorScheme.tertiary
    val n = SPARK_SYMBOLS.size

    Box(
        modifier = modifier
            .width(widthDp.dp)
            .height(riseDp.dp)
            .clearAndSetSemantics { }
    ) {
        SPARK_SYMBOLS.forEachIndexed { i, symbol ->
            val phase = i.toFloat() / n
            val slot = (i * 7) % n
            val x = (slot + 0.5f) / n * (widthDp - 20f)

            Text(
                text = symbol,
                color = if (i % 2 == 0) colorA else colorB,
                fontSize = if (symbol.length > 1 || symbol[0].code < 0x2700) 20.sp else 18.sp,
                modifier = Modifier
                    .align(Alignment.BottomStart)
                    .offset(x = x.dp)
                    .graphicsLayer {
                        val t = (progress.value + phase) % 1f
                        translationY = -t * riseDp * density
                        alpha = sin(PI * t).toFloat().coerceIn(0f, 1f)
                        val scale = (0.6f + 0.6f * sin(PI * t).toFloat()) * pulse.value
                        scaleX = scale
                        scaleY = scale
                        rotationZ = (t - 0.5f) * 60f
                    }
            )
        }
    }
}
''')

print(">> THINKING ANIMATION applied: waiting text removed, math symbols & stars only (cancel button kept).")
